import React, { useRef, useState } from 'react';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { uploadImageFile } from '../utils/uploadImage';
import { auth } from '../firebaseConfig';
import { useCaptures } from '../hooks/useCaptures';
import { ImageModal } from './SessionImageViewer/ImageModal';
import { useTranslation } from '../hooks/useTranslation';

const BLOCK_NAME_TRANSLATIONS = {
  'Calentamiento': 'Warm-up',
  'Vuelta a la calma': 'Cool-down',
  'Activación táctica': 'Tactical Activation',
  'Ejercicio de pase en triángulos': 'Triangle Passing Drill',
  'Partido posicional 5v5': '5v5 Positional Game',
  'Defensa 8v8 en bloque': '8v8 Block Defense',
  'Transición defensa-ataque': 'Defense-to-Attack Transition',
  'Partido condicionado': 'Conditioned Match'
};

const BlockEditor = ({ block, index, totalBlocks, handleUpdateBlock, handleDeleteBlock, handleDuplicateBlock, handleMoveBlock, teamId, sessionId }) => {
  const { isEn } = useTranslation();
  const fileInputRef = useRef(null);
  const [showCaptureModal, setShowCaptureModal] = useState(false);
  const [showViewerModal, setShowViewerModal] = useState(false);
  const { captures } = useCaptures(teamId);

  const getBlockDisplayName = (name) => {
    if (!name) return '';
    if (isEn && BLOCK_NAME_TRANSLATIONS[name]) return BLOCK_NAME_TRANSLATIONS[name];
    return name;
  };

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: block.id });

  const style = {
    transform: transform ? CSS.Transform.toString(transform) : undefined,
    transition,
    opacity: isDragging ? 0.5 : 1,
    position: 'relative',
    zIndex: isDragging ? 999 : 'auto',
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    window.dispatchEvent(new CustomEvent('m11-loading', { detail: { show: true, message: isEn ? 'Processing diagram...' : 'Procesando diagrama...' } }));
    try {
      const isSvg = file.type === 'image/svg+xml' || file.name?.toLowerCase().endsWith('.svg');
      const isPng = file.type === 'image/png' || file.name?.toLowerCase().endsWith('.png');

      const reader = new FileReader();
      reader.onload = (event) => {
        if (isSvg) {
          const svgUrl = event.target.result;
          handleUpdateBlock(block.id, 'imagenProtocolo', svgUrl);
          handleUpdateBlock(block.id, 'imageUrl', svgUrl);
          window.dispatchEvent(new CustomEvent('m11-loading', { detail: { show: false } }));
          return;
        }

        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          
          const MAX_WIDTH = 800;
          const MAX_HEIGHT = 800;
          
          if (width > height) {
            if (width > MAX_WIDTH) {
              height *= MAX_WIDTH / width;
              width = MAX_WIDTH;
            }
          } else {
            if (height > MAX_HEIGHT) {
              width *= MAX_HEIGHT / height;
              height = MAX_HEIGHT;
            }
          }
          
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, width, height);
          
          const mime = isPng ? 'image/png' : 'image/jpeg';
          const base64Url = canvas.toDataURL(mime, isPng ? 0.92 : 0.75);
          handleUpdateBlock(block.id, 'imagenProtocolo', base64Url);
          handleUpdateBlock(block.id, 'imageUrl', base64Url);
          window.dispatchEvent(new CustomEvent('m11-loading', { detail: { show: false } }));
        };
        img.onerror = () => {
          alert(isEn ? 'Error processing image.' : 'Error al procesar la imagen.');
          window.dispatchEvent(new CustomEvent('m11-loading', { detail: { show: false } }));
        };
        img.src = event.target.result;
      };
      reader.onerror = () => {
        alert(isEn ? 'Error reading file.' : 'Error al leer el archivo.');
        window.dispatchEvent(new CustomEvent('m11-loading', { detail: { show: false } }));
      };
      reader.readAsDataURL(file);
    } catch (err) {
      console.error(err);
      alert(isEn ? 'Error processing image.' : 'Error al procesar la imagen.');
      window.dispatchEvent(new CustomEvent('m11-loading', { detail: { show: false } }));
    } finally {
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  return (
    <div ref={setNodeRef} style={style} className="block-editor-card">
      <div className="block-editor-header">
        {/* Fila 1 (DEF-M07-03): badge numérico + input de título (flex:1 >=120px) + botón borrar */}
        <div className="block-header-row-primary">
          <span className="block-number">{index + 1}</span>
          <input 
            type="text" 
            className="block-title-input" 
            value={getBlockDisplayName(block.name)} 
            onChange={e => handleUpdateBlock(block.id, 'name', e.target.value)} 
            onFocus={e => e.target.select()}
            placeholder={isEn ? "Exercise name" : "Nombre del ejercicio"} 
            title={getBlockDisplayName(block.name)}
          />
          <button 
            type="button"
            className="btn-del-icon" 
            onClick={() => handleDeleteBlock(block.id)}
            style={{ minWidth: '48px', minHeight: '48px', display: 'flex', alignItems: 'center', justifyContent: 'center', touchAction: 'manipulation', flexShrink: 0 }}
            title={isEn ? "Delete block" : "Eliminar bloque"}
            aria-label={isEn ? "Delete block" : "Eliminar bloque"}
          >
            ✕
          </button>
        </div>

        {/* Fila 2 (DEF-M07-03): hamburguesa + ▲ + ▼ + duplicar (targets >=48dp) */}
        <div className="block-header-row-actions">
          <div 
            className="drag-handle" 
            {...attributes} 
            {...listeners} 
            style={{ cursor: 'grab', padding: '8px 12px', display: 'flex', alignItems: 'center', justifyContent: 'center', minWidth: '48px', minHeight: '48px', touchAction: 'none', flexShrink: 0 }}
            title={isEn ? "Drag to reorder" : "Arrastrar para reordenar"}
            aria-label={isEn ? "Drag to reorder" : "Arrastrar para reordenar"}
          >
            <span style={{ fontSize: '18px', color: 'var(--text-muted)' }}>☰</span>
          </div>
          {handleMoveBlock && (
            <div className="touch-reorder-group" style={{ display: 'flex', alignItems: 'center', gap: '4px', flexShrink: 0 }}>
              <button
                type="button"
                className="btn-touch-reorder btn-move-up"
                onClick={() => handleMoveBlock(index, -1)}
                disabled={index === 0}
                style={{
                  minWidth: '48px',
                  minHeight: '48px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  background: 'transparent',
                  border: '1px solid var(--border-color, rgba(255,255,255,0.12))',
                  borderRadius: '8px',
                  cursor: index === 0 ? 'not-allowed' : 'pointer',
                  color: index === 0 ? 'var(--text-muted, #64748b)' : 'var(--text-primary, #ffffff)',
                  opacity: index === 0 ? 0.3 : 1,
                  fontSize: '15px',
                  touchAction: 'manipulation'
                }}
                title={isEn ? "Move exercise up" : "Mover ejercicio arriba"}
                aria-label={isEn ? "Move exercise up" : "Mover ejercicio arriba"}
              >
                ▲
              </button>
              <button
                type="button"
                className="btn-touch-reorder btn-move-down"
                onClick={() => handleMoveBlock(index, 1)}
                disabled={index >= (totalBlocks || 1) - 1}
                style={{
                  minWidth: '48px',
                  minHeight: '48px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  background: 'transparent',
                  border: '1px solid var(--border-color, rgba(255,255,255,0.12))',
                  borderRadius: '8px',
                  cursor: index >= (totalBlocks || 1) - 1 ? 'not-allowed' : 'pointer',
                  color: index >= (totalBlocks || 1) - 1 ? 'var(--text-muted, #64748b)' : 'var(--text-primary, #ffffff)',
                  opacity: index >= (totalBlocks || 1) - 1 ? 0.3 : 1,
                  fontSize: '15px',
                  touchAction: 'manipulation'
                }}
                title={isEn ? "Move exercise down" : "Mover ejercicio abajo"}
                aria-label={isEn ? "Move exercise down" : "Mover ejercicio abajo"}
              >
                ▼
              </button>
            </div>
          )}
          {handleDuplicateBlock && (
            <button
              type="button"
              className="btn-duplicate-block"
              title={isEn ? "Duplicate block" : "Duplicar bloque"}
              aria-label={isEn ? "Duplicate block" : "Duplicar bloque"}
              onClick={() => handleDuplicateBlock(block)}
              style={{ minWidth: '48px', minHeight: '48px', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'transparent', border: '1px solid var(--border-light, #e2e8f0)', borderRadius: '8px', cursor: 'pointer', color: 'var(--text-secondary)', transition: 'all 0.2s', flexShrink: 0 }}
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>
            </button>
          )}
        </div>
      </div>
      
      <div className="block-editor-body">
        <div className="form-row-compact">
          <div className="form-group">
            <label>{isEn ? 'Minutes' : 'Minutos'}</label>
            <input 
              type="number" 
              value={block.duration || ''} 
              onChange={e => handleUpdateBlock(block.id, 'duration', parseInt(e.target.value) || 0)} 
              placeholder="15" 
              min="1"
            />
          </div>
          <div className="form-group">
            <label>{isEn ? 'Intensity' : 'Intensidad'}</label>
            <select 
              value={block.intensity || 'Media'} 
              onChange={e => handleUpdateBlock(block.id, 'intensity', e.target.value)}
            >
              <option value="Baja">{isEn ? 'Low' : 'Baja'}</option>
              <option value="Media">{isEn ? 'Medium' : 'Media'}</option>
              <option value="Alta">{isEn ? 'High' : 'Alta'}</option>
            </select>
          </div>
          <div className="form-group">
            <label>{isEn ? 'Content' : 'Contenido'}</label>
            <select 
              value={block.type || 'Técnica'} 
              onChange={e => handleUpdateBlock(block.id, 'type', e.target.value)}
            >
              <option value="Física">{isEn ? 'Warm-up / Physical' : 'Calentamiento/Físico'}</option>
              <option value="Técnica">{isEn ? 'Technical' : 'Técnico'}</option>
              <option value="Táctica">{isEn ? 'Tactical' : 'Táctico'}</option>
              <option value="Partido">{isEn ? 'Match / Game' : 'Partido R.'}</option>
            </select>
          </div>
        </div>
        
        <div className="form-group full">
          <label>{isEn ? 'Description & Rules' : 'Descripción y Reglas'}</label>
          <textarea 
            value={block.description || ''} 
            onChange={e => handleUpdateBlock(block.id, 'description', e.target.value)} 
            placeholder={isEn ? "Describe the exercise, restrictions, scoring..." : "Describe el ejercicio, restricciones, puntuación..."}
          ></textarea>
        </div>

          {/* Módulo de Subir Imagen / Diagrama */}
          {(() => {
            const blockImg = block.imageUrl || block.imagenProtocolo || block.image || block.photo || block.previewUrl;
            return (
              <div className="form-group full">
                <label>{isEn ? 'Exercise Image / Diagram' : 'Imagen / Diagrama del Ejercicio'}</label>
                {blockImg && (
                  <div style={{ position: 'relative', marginBottom: '10px' }}>
                    <img 
                      src={blockImg} 
                      alt={isEn ? "Exercise diagram" : "Diagrama del ejercicio"} 
                      onClick={() => setShowViewerModal(true)}
                      style={{ width: '100%', maxHeight: '200px', objectFit: 'contain', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: '#f8fafc', cursor: 'zoom-in' }} 
                    />
                    <div style={{ position: 'absolute', bottom: 8, left: 8, display: 'flex', gap: '6px' }}>
                      <button
                        type="button"
                        onClick={() => setShowViewerModal(true)}
                        style={{ background: 'rgba(0,0,0,0.75)', color: '#FFF', border: '1px solid #D4A843', borderRadius: '6px', padding: '4px 8px', fontSize: '11px', fontWeight: 'bold', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px' }}
                      >
                        🔍 {isEn ? 'View / Annotate' : 'Ver / Anotar'}
                      </button>
                    </div>
                    <button 
                      onClick={() => {
                        handleUpdateBlock(block.id, 'imagenProtocolo', null);
                        handleUpdateBlock(block.id, 'imageUrl', null);
                        handleUpdateBlock(block.id, 'image', null);
                        handleUpdateBlock(block.id, 'photo', null);
                        handleUpdateBlock(block.id, 'previewUrl', null);
                      }}
                      title={isEn ? "Delete image" : "Eliminar imagen"}
                      style={{ position: 'absolute', top: 5, right: 5, backgroundColor: 'rgba(255,0,0,0.8)', color: 'white', border: 'none', borderRadius: '50%', width: '30px', height: '30px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                    >✕</button>
                  </div>
                )}
                {showViewerModal && blockImg && (
                  <ImageModal
                    isOpen={showViewerModal}
                    onClose={() => setShowViewerModal(false)}
                    images={[blockImg]}
                    initialIndex={0}
                    exercisesData={[{
                      name: getBlockDisplayName(block.name) || (isEn ? 'Exercise' : 'Ejercicio'),
                      type: block.type || (isEn ? 'Tactical' : 'Táctico'),
                      duration: block.duration || 15,
                      description: block.description || ''
                    }]}
                  />
                )}
                <div className="block-image-actions">
                  <input 
                    type="file" 
                    accept="image/*, .png, .jpg, .jpeg, .webp, .svg, .gif, .avif, .bmp" 
                    style={{ display: 'none' }} 
                    ref={fileInputRef}
                    onChange={handleImageUpload}
                  />
                  <button
                    type="button"
                    className="btn-outline btn-block-img-action"
                    onClick={() => fileInputRef.current?.click()}
                    title={isEn ? 'Upload Image' : 'Subir Imagen'}
                  >
                    <span className="btn-img-icon">📸</span>
                    <span className="btn-img-text">{isEn ? 'Upload Image' : 'Subir Imagen'}</span>
                  </button>
                  <button
                    type="button"
                    className="btn-outline btn-block-img-action"
                    onClick={() => setShowCaptureModal(true)}
                    title={isEn ? 'Select Capture' : 'Seleccionar Captura'}
                  >
                    <span className="btn-img-icon">🖼️</span>
                    <span className="btn-img-text">{isEn ? 'Select Capture' : 'Seleccionar Captura'}</span>
                  </button>
                </div>
              </div>
            );
          })()}
      </div>

      {showCaptureModal && (
        <div className="modal-overlay" onClick={() => setShowCaptureModal(false)} style={{ zIndex: 9999 }}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <h3>{isEn ? 'Select Capture' : 'Seleccionar Captura'}</h3>
              <button className="btn-close" onClick={() => setShowCaptureModal(false)}>✕</button>
            </div>
            <div className="modal-body">
              {captures && captures.length > 0 ? (
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))', gap: '10px' }}>
                  {captures.map(cap => (
                    <div 
                      key={cap.id} 
                      style={{ cursor: 'pointer', border: '2px solid transparent', borderRadius: '8px', overflow: 'hidden' }}
                        onClick={() => {
                          const capUrl = cap.thumbnail || cap.url || cap.dataUrl || cap.imageUrl;
                          handleUpdateBlock(block.id, 'boardCaptureUrl', capUrl);
                          handleUpdateBlock(block.id, 'imagenProtocolo', capUrl);
                          handleUpdateBlock(block.id, 'imageUrl', capUrl);
                          setShowCaptureModal(false);
                        }}
                    >
                      <img src={cap.url} alt={cap.title} style={{ width: '100%', height: '100px', objectFit: 'cover' }} />
                      <p style={{ fontSize: '12px', textAlign: 'center', padding: '4px', margin: 0, backgroundColor: '#f1f5f9' }}>
                        {cap.title || (isEn ? 'Capture' : 'Captura')}
                      </p>
                    </div>
                  ))}
                </div>
              ) : (
                <p>{isEn ? 'No captures available.' : 'No hay capturas disponibles.'}</p>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default BlockEditor;
