import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useSearchParams, useParams, useNavigate, useLocation } from 'react-router-dom';
import { generateSessionPDF } from '../utils/pdfGenerator';
import LiveFieldSession from '../components/LiveFieldSession';
import { useSessions } from '../hooks/useSessions';
import { usePlayers } from '../hooks/usePlayers';
import { useAuth } from '../context/AuthContext';
import { showToast } from '../utils/toast';
import { useTeams } from '../hooks/useTeams';
import { usePlan, LIMITS } from '../hooks/usePlan';
import UpgradeModal from '../components/UpgradeModal';
import { storage, db } from '../firebaseConfig';
import { ref, uploadBytesResumable, getDownloadURL, deleteObject } from 'firebase/storage';
import { collection, getDocs, query, orderBy, doc, deleteDoc, writeBatch } from '../firebase/firestore-proxy';
import { useCaptures } from '../hooks/useCaptures';
import { useExercises } from '../hooks/useExercises';
import { downloadJSON, downloadImage } from '../utils/download.js';
import { generateGoogleCalendarUrl, generateICSContent, downloadICSFile } from '../utils/calendarHelper';
import { shareSessionToFirestore, getSharedSession, exportSessionToJSONFile, exportSessionToICSFile, parseSessionFile } from '../utils/sessionSharing';
import { Share2, Link as LinkIcon, Download, Upload, Copy, Check, Calendar, ArrowRight, Star } from 'lucide-react';
import { normalizeText } from '../utils/normalizeInput';
import { useTranslation } from '../hooks/useTranslation';
import { SpellCheckedInput } from '../components/ui/SpellCheckedInput';
import { SpellCheckedTextarea } from '../components/ui/SpellCheckedTextarea';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  TouchSensor,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import './Sesiones.css';
import BlockEditor from '../components/BlockEditor';
import { ImageModal } from '../components/SessionImageViewer/ImageModal';
import SessionPlayerRating from '../components/session/SessionPlayerRating';
import GatedFeature from '../components/GatedFeature';

const Sesiones = () => {
  const { user, activeTeamId, getTeamPath } = useAuth();
  const { activeTeam } = useTeams();
  const { isPro, limits, isProActive } = usePlan();
  const { sessions, addSession, updateSession, removeSession, loading: loadingSessions } = useSessions(activeTeamId);
  const { players, loading: loadingPlayers } = usePlayers(activeTeamId);
  const { captures, loading: loadingCaptures, removeCapture } = useCaptures(activeTeamId);
  const { t, isEn, locale, fmtPlural, getWeekdays } = useTranslation();
  const { exercises, loading: loadingExercises, removeExercise } = useExercises(activeTeamId);
  const pizarras = (exercises || []).filter(e => e.type === 'pizarra');

  const [activeTab, setActiveTab] = useState('sessions'); // 'sessions' | 'captures' | 'animations'
  const [upgradeModal, setUpgradeModal] = useState({ open: false, message: '' });

  // Custom Confirmation Dialog State
  const [modalConfig, setModalConfig] = useState({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: null,
    isConfirm: false,
  });

  const showAlert = (title, message) => {
    return new Promise((resolve) => {
      setModalConfig({
        isOpen: true,
        title,
        message,
        onConfirm: () => {
          setModalConfig(prev => ({ ...prev, isOpen: false }));
          resolve();
        },
        isConfirm: false
      });
    });
  };

  const showConfirm = (title, message) => {
    return new Promise((resolve) => {
      setModalConfig({
        isOpen: true,
        title,
        message,
        onConfirm: (res) => {
          setModalConfig(prev => ({ ...prev, isOpen: false }));
          resolve(res);
        },
        isConfirm: true
      });
    });
  };

  const [viewMode, setViewMode] = useState('list'); // 'list' | 'edit'
  const [selectedSession, setSelectedSession] = useState(null);
  const [ratingModalSession, setRatingModalSession] = useState(null);
  const [selectedCapture, setSelectedCapture] = useState(null);
  const [selectedAnimation, setSelectedAnimation] = useState(null);
  const [editData, setEditData] = useState(null);
  const [showLiveField, setShowLiveField] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);
  
  const [searchParams, setSearchParams] = useSearchParams();
  const { id: urlSessionId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const [shareModal, setShareModal] = useState({ open: false, session: null, shareUrl: '', shareId: '', loading: false, copied: false });
  const [importModal, setImportModal] = useState({ open: false, activeTab: 'link', inputVal: '', loading: false, previewSession: null, file: null, error: '' });

  // Ocultar BottomNav mientras se edita una sesión en móvil para evitar doble barra sobrepuesta
  useEffect(() => {
    if (viewMode === 'edit') {
      document.body.classList.add('session-editor-active');
      return () => {
        document.body.classList.remove('session-editor-active');
      };
    } else {
      document.body.classList.remove('session-editor-active');
    }
  }, [viewMode]);

  // Manejador para compartir sesión (Web Share API + Clipboard Fallback)
  const handleShareSession = async (sessionToShare) => {
    if (!sessionToShare) return;

    let shareUrl = '';
    let shareId = '';

    try {
      // Guardar de forma AWAIT en Firestore antes de generar la URL para asegurar que la sesión exista públicamente de inmediato
      const result = await shareSessionToFirestore(sessionToShare, user, activeTeam);
      shareUrl = result.shareUrl;
      shareId = result.shareId;
    } catch (err) {
      console.warn('[handleShareSession] Error al guardar en Firestore:', err);
      shareId = sessionToShare.id || `ses_${Date.now()}`;
      const baseUrl = window?.location?.origin || 'https://www.mister11.app';
      shareUrl = `${baseUrl}/shared/session/${shareId}`;
    }

    const sessionTitle = sessionToShare.title || sessionToShare.nombre || sessionToShare.titulo || (isEn ? 'Training Session' : 'Sesión de Entrenamiento');

    // 1. Web Share API nativo si está disponible
    if (navigator.share) {
      try {
        await navigator.share({
          title: `${sessionTitle} - Míster11`,
          text: isEn ? `Sharing this training session: ${sessionTitle}` : `Te comparto esta sesión de entrenamiento: ${sessionTitle}`,
          url: shareUrl,
        });
        return;
      } catch (err) {
        if (err.name === 'AbortError') {
          return;
        }
        console.warn('[handleShareSession] Falló Web Share API, reintentando con portapapeles:', err);
      }
    }

    // 2. Fallback a Portapapeles
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(shareUrl);
        showToast(isEn ? 'Link copied to clipboard!' : '¡Enlace copiado al portapapeles!', 'success');
        return;
      }
    } catch (clipErr) {
      console.warn('[handleShareSession] Falló el portapapeles:', clipErr);
    }

    // 3. Fallback modal interactivo
    setShareModal({
      open: true,
      session: sessionToShare,
      shareUrl,
      shareId,
      loading: false,
      copied: false,
    });
  };

  const handleCopyShareUrl = () => {
    if (!shareModal.shareUrl) return;
    navigator.clipboard.writeText(shareModal.shareUrl);
    setShareModal(prev => ({ ...prev, copied: true }));
    showToast(isEn ? 'Link copied to clipboard!' : '¡Enlace copiado al portapapeles!', 'success');
    setTimeout(() => setShareModal(prev => ({ ...prev, copied: false })), 2000);
  };

  // Auto-detectar importShareId en los parámetros de la URL
  useEffect(() => {
    const shareIdParam = searchParams.get('importShareId');
    if (shareIdParam) {
      setImportModal({ open: true, activeTab: 'link', inputVal: shareIdParam, loading: true, previewSession: null, file: null, error: '' });
      getSharedSession(shareIdParam).then(data => {
        if (data) {
          setImportModal(prev => ({ ...prev, loading: false, previewSession: data }));
        } else {
          setImportModal(prev => ({ ...prev, loading: false, error: isEn ? 'No shared session found with that link.' : 'No se encontró ninguna sesión compartida con ese enlace.' }));
        }
      }).catch(() => {
        setImportModal(prev => ({ ...prev, loading: false, error: isEn ? 'Error loading the shared session.' : 'Error al cargar la sesión compartida.' }));
      });
      setSearchParams({}, { replace: true });
    }
  }, [searchParams, setSearchParams]);

  // Manejador de búsqueda/previa por link o ID en el modal de importación
  const handleFetchSharePreview = async () => {
    const queryVal = importModal.inputVal.trim();
    if (!queryVal) {
      setImportModal(prev => ({ ...prev, error: isEn ? 'Please enter a valid link or share code.' : 'Por favor, introduce un enlace o código de compartir válido.' }));
      return;
    }

    try {
      setImportModal(prev => ({ ...prev, loading: true, error: '', previewSession: null }));
      const data = await getSharedSession(queryVal);
      if (data) {
        setImportModal(prev => ({ ...prev, loading: false, previewSession: data }));
      } else {
        setImportModal(prev => ({ ...prev, loading: false, error: isEn ? 'Shared session not found. Check the link or code.' : 'No se encontró la sesión compartida. Verifica el enlace o código.' }));
      }
    } catch (err) {
      setImportModal(prev => ({ ...prev, loading: false, error: isEn ? 'Error querying the shared session.' : 'Error al consultar la sesión compartida.' }));
    }
  };

  // Manejador para procesar archivo .m11session / .json cargado
  const handleSessionFileUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      setImportModal(prev => ({ ...prev, loading: true, error: '', file, previewSession: null }));
      const parsed = await parseSessionFile(file);
      setImportModal(prev => ({ ...prev, loading: false, previewSession: parsed }));
    } catch (err) {
      setImportModal(prev => ({ ...prev, loading: false, error: err.message || (isEn ? 'Error reading the file.' : 'Error al leer el archivo.') }));
    }
  };

  // Manejador para confirmar la importación a la lista de sesiones del equipo activo
  const handleConfirmImportSession = async () => {
    if (!importModal.previewSession) return;
    try {
      setImportModal(prev => ({ ...prev, loading: true }));
      const s = importModal.previewSession;
      const sessionPayload = {
        title: s.title || s.nombre || 'Sesión Importada',
        category: s.category || s.categoria || 'Táctica',
        duration: Number(s.duration || s.duracion || 90),
        intensity: s.intensity || s.intensidad || 'Media',
        materials: s.materials || s.material || '',
        objectives: s.objectives || s.objetivo || '',
        date: new Date().toISOString().split('T')[0],
        time: '18:00',
        blocks: s.blocks || s.bloques || [],
        importedAt: new Date().toISOString(),
      };
      await addSession(sessionPayload);
      showToast(isEn ? 'Session imported successfully to your team!' : '¡Sesión importada con éxito en tu equipo!', 'success');
      setImportModal({ open: false, activeTab: 'link', inputVal: '', loading: false, previewSession: null, file: null, error: '' });
    } catch (err) {
      console.error('Error al importar la sesión:', err);
      showAlert('Error', isEn ? 'Could not save the imported session to your team.' : 'No se pudo guardar la sesión importada en tu equipo.');
      setImportModal(prev => ({ ...prev, loading: false }));
    }
  };
  const [pdfPreview, setPdfPreview] = useState(null);
  const fileInputRef = useRef(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [exportingId, setExportingId] = useState(null);

  const handleExportMP4 = async (anim) => {
    if (!anim) return;
    
    // Si ya existe la URL de video en la nube, descargamos directamente
    if (anim.videoUrl) {
      try {
        setExportingId(anim.id);
        const response = await fetch(anim.videoUrl);
        const blob = await response.blob();
        const reader = new FileReader();
        reader.readAsDataURL(blob);
        reader.onloadend = async () => {
          try {
            const base64data = reader.result.split(',')[1];
            const fileType = anim.videoMimeType && anim.videoMimeType.includes('mp4') ? 'mp4' : 'webm';
            const { downloadVideo } = await import('../utils/download.js');
            await downloadVideo(base64data, `animacion_sesion.${fileType}`, anim.videoMimeType || 'video/webm');
          } catch (e) {
            console.error("Error al procesar descarga de video existente:", e);
            showToast(isEn ? 'Error saving the video locally.' : 'Error al guardar el video localmente.', 'error');
          } finally {
            setExportingId(null);
          }
        };
      } catch (err) {
        console.error("Fallo al descargar video pre-renderizado:", err);
        // Fallback: renderizar en segundo plano si el enlace de storage no responde
        setExportingId(anim.id);
        showToast(isEn ? 'Trying to render animation in the background...' : 'Intentando renderizar animación en segundo plano...', 'info');
      }
    } else {
      // Si no existe videoUrl (animación no compilada), disparamos la exportación en segundo plano
      setExportingId(anim.id);
      showToast(isEn ? 'Generating animation video in the background. Please wait...' : 'Generando video de la animación en segundo plano. Por favor, espera...', 'info');
    }
  };

  useEffect(() => {
    const handleExportMessage = async (event) => {
      if (event.data && event.data.type === 'EXPORT_DONE') {
        const { base64data, filename, mimeType } = event.data;
        try {
          const { downloadVideo } = await import('../utils/download.js');
          const finalExt = filename.includes('mp4') ? 'mp4' : 'webm';
          await downloadVideo(base64data, `animacion_sesion.${finalExt}`, mimeType);
          showToast(isEn ? '🎉 Animation downloaded successfully' : '🎉 Animación descargada exitosamente', 'success');
        } catch (err) {
          console.error('Error descargando video renderizado en backend:', err);
          await showAlert('Error', isEn ? 'Could not download the rendered animation.' : 'No se pudo descargar la animación renderizada.');
        } finally {
          setExportingId(null);
        }
      } else if (event.data === 'EXPORT_ERROR') {
        await showAlert('Error', isEn ? 'Error processing the render in the tactical board.' : 'Error al procesar el renderizado en la pizarra táctica.');
        setExportingId(null);
      }
    };

    window.addEventListener('message', handleExportMessage);
    return () => {
      window.removeEventListener('message', handleExportMessage);
    };
  }, []);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(TouchSensor, {
      activationConstraint: {
        delay: 200,
        tolerance: 5,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (!over) return;
    if (active.id !== over.id) {
      setEditData(prev => {
        const oldIndex = prev.blocks.findIndex(b => b.id === active.id);
        const newIndex = prev.blocks.findIndex(b => b.id === over.id);
        return {
          ...prev,
          blocks: arrayMove(prev.blocks, oldIndex, newIndex)
        };
      });
    }
  };

  const categoryFilters = [
    { key: 'Todas', labelKey: 'sesiones.categories.all' },
    { key: 'Técnica', labelKey: 'sesiones.categories.tecnica' },
    { key: 'Táctica', labelKey: 'sesiones.categories.tactica' },
    { key: 'Física', labelKey: 'sesiones.categories.fisica' },
    { key: 'Mixta', labelKey: 'sesiones.categories.mixta' },
  ];
  const [catFilter, setCatFilter] = useState('Todas');

  // FASE 5: Selector DÍA | SEMANA | MES y fecha activa
  const [calendarView, setCalendarView] = useState('semana'); // 'dia' | 'semana' | 'mes'
  const [selectedCalendarDate, setSelectedCalendarDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [monthBottomSheetOpen, setMonthBottomSheetOpen] = useState(false);

  const CATEGORY_COLORS = {
    'Técnica': '#3B82F6',
    'Táctica': '#10B981',
    'Física': '#F97316',
    'Mixta': '#A855F7',
    'General': '#6B7280',
    'Partido': '#D4A843',
  };

  const getSessionsForDate = (dateObj) => {
    if (!dateObj || typeof dateObj.getFullYear !== 'function' || !Array.isArray(sessions)) return [];
    const y = dateObj.getFullYear();
    const m = String(dateObj.getMonth() + 1).padStart(2, '0');
    const d = String(dateObj.getDate()).padStart(2, '0');
    const dStr = `${y}-${m}-${d}`;
    return (sessions || []).filter(s => s && (s.date === dStr || s.fecha === dStr));
  };

  const filteredSessions = useMemo(() => {
    let list = Array.isArray(sessions) ? sessions.filter(Boolean) : [];
    if (catFilter !== 'Todas') {
      list = list.filter(s => s && (s.category || s.categoria || '') === catFilter);
    }
    if (calendarView === 'dia') {
      list = list.filter(s => s && (s.date === selectedCalendarDate || s.fecha === selectedCalendarDate));
    }
    return list;
  }, [sessions, catFilter, calendarView, selectedCalendarDate]);

  // --- LIST MODE FUNCTIONS ---
  const parseSessionDateTime = (dateStr, timeStr) => {
    if (!dateStr) return new Date();
    const [year, month, day] = dateStr.split('-').map(Number);
    const [hour, minute] = (timeStr || '00:00').split(':').map(Number);
    return new Date(year, month - 1, day, hour, minute);
  };

  const handleAddToGoogleCalendar = (session) => {
    const startDate = parseSessionDateTime(session.date, session.time);
    const durationMin = session.duration || session.duracion || 90;
    const endDate = new Date(startDate.getTime() + durationMin * 60 * 1000);
    const url = generateGoogleCalendarUrl({
      title: `ENTRENAMIENTO: ${session.title || session.titulo || 'Sesión'}`,
      description: `Sesión de entrenamiento. Objetivos: ${session.objectives || ''}. Carga: ${session.intensity || 'Media'}.`,
      location: 'Campo de entrenamiento',
      startDate,
      endDate
    });
    window.open(url, '_blank');
  };

  const handleExportICS = (session) => {
    const startDate = parseSessionDateTime(session.date, session.time);
    const durationMin = session.duration || session.duracion || 90;
    const endDate = new Date(startDate.getTime() + durationMin * 60 * 1000);
    const icsContent = generateICSContent([{
      id: session.id || `session-${Date.now()}`,
      title: `ENTRENAMIENTO: ${session.title || session.titulo || 'Sesión'}`,
      description: `Sesión de entrenamiento. Objetivos: ${session.objectives || ''}. Carga: ${session.intensity || 'Media'}.`,
      location: 'Campo de entrenamiento',
      startDate,
      endDate
    }]);
    downloadICSFile(`entrenamiento_${(session.title || 'sesion').replace(/\s+/g, '_')}.ics`, icsContent);
  };

  const handleExportAllSessionsICS = () => {
    if (sessions.length === 0) return;
    const events = sessions.map(s => {
      const startDate = parseSessionDateTime(s.date, s.time);
      const durationMin = s.duration || s.duracion || 90;
      const endDate = new Date(startDate.getTime() + durationMin * 60 * 1000);
      return {
        id: s.id,
        title: `ENTRENAMIENTO: ${s.title || s.titulo || 'Sesión'}`,
        description: `Sesión de entrenamiento. Objetivos: ${s.objectives || ''}. Carga: ${s.intensity || 'Media'}.`,
        location: 'Campo de entrenamiento',
        startDate,
        endDate
      };
    });
    const icsContent = generateICSContent(events);
    downloadICSFile(`calendario_entrenamientos_${activeTeam?.nombre?.replace(/\s+/g, '_') || 'equipo'}.ics`, icsContent);
  };

  const initNewSessionData = useCallback(() => ({
    title: '',
    date: new Date().toISOString().split('T')[0],
    time: '18:00',
    category: 'Táctica',
    intensity: 'Media',
    duration: 90,
    players: (players || []).map(p => p.id), // All selected by default
    files: [],
    objectives: '',
    materials: 'Balones, petos, conos, setas',
    linkedPizarraId: '',
    blocks: [
      { id: Date.now() + Math.random(), name: isEn ? 'Warm-up' : 'Calentamiento', duration: 15, type: isEn ? 'Physical' : 'Física', description: '', imageUrl: null, imagenProtocolo: null }
    ]
  }), [players, isEn]);

  const handleCreateNew = () => {
    if (!isPro && sessions.length >= limits.SESSIONS) {
      setUpgradeModal({ open: true, message: isEn ? `You have reached the limit of ${limits.SESSIONS} sessions on the free plan.` : `Has alcanzado el límite de ${limits.SESSIONS} sesiones del plan gratuito.` });
      return;
    }
    setEditData(initNewSessionData());
    setViewMode('edit');
    if (!location.pathname.endsWith('/sesiones/nueva')) {
      navigate('/sesiones/nueva');
    }
  };

  const handleBackToList = () => {
    setViewMode('list');
    setEditData(null);
    if (location.pathname !== '/sesiones') {
      navigate('/sesiones');
    }
  };

  const handleEditSession = (sessionToEdit, e) => {
    if (e && typeof e.stopPropagation === 'function') {
      e.stopPropagation();
    }
    
    // Detectar si sessionToEdit es en realidad un evento SyntheticEvent (ej: al pasar onClick={handleEditSession})
    let sess = sessionToEdit;
    if (sess && (sess.nativeEvent || sess._reactName || (sess.target && sess.preventDefault))) {
      sess = selectedSession;
    }
    if (!sess) sess = selectedSession;

    if (!sess || typeof sess !== 'object') {
      console.warn('[handleEditSession] No se proporcionó una sesión válida.');
      showToast(isEn ? 'Error: Session to edit not found' : 'Error: No se encontró la sesión a editar', 'error');
      return;
    }

    try {
      console.log('[handleEditSession] Preparando edición para sesión ID:', sess.id, sess.title || sess.nombre);
      
      const rawBlocks = sess.blocks || sess.bloques || [];
      const mappedBlocks = Array.isArray(rawBlocks)
        ? rawBlocks
            .filter(b => b && typeof b === 'object')
            .map((b, idx) => {
              let blockImg = b.imageUrl || b.imagenProtocolo || b.image || b.photo || b.previewUrl || b.canvasData || b.boardCapture || b.pizarraUrl || null;
              
              // Sanitizar imagen: asegurar que sea una string válida (DataURL o URL HTTPS) y no un objeto File/Blob
              if (blockImg && typeof blockImg !== 'string') {
                if (typeof blockImg === 'object') {
                  blockImg = blockImg.url || blockImg.dataUrl || blockImg.src || null;
                } else {
                  blockImg = null;
                }
              }

              return {
                id: b.id || `block_${idx}_${Date.now()}`,
                name: String(b.name || b.nombre || b.titulo || `Bloque ${idx + 1}`),
                duration: Number(b.duration || b.duracion || b.tiempo) || 15,
                type: String(b.type || b.tipo || 'Táctica'),
                description: String(b.description || b.descripcion || ''),
                imageUrl: blockImg,
                imagenProtocolo: blockImg,
              };
            })
        : [];

      const cleanEditData = {
        id: sess.id || null,
        title: String(sess.title || sess.nombre || sess.titulo || ''),
        date: String(sess.date || sess.fecha || new Date().toISOString().split('T')[0]),
        time: String(sess.time || sess.hora || '18:00'),
        duration: Number(sess.duration || sess.duracion) || 90,
        category: String(sess.category || sess.categoria || 'General'),
        intensity: String(sess.intensity || sess.intensidad || 'Media'),
        materials: String(sess.materials || sess.material || ''),
        objectives: String(sess.objectives || sess.objetivo || ''),
        players: Array.isArray(sess.players) ? sess.players : (Array.isArray(sess.convocados) ? sess.convocados : []),
        files: Array.isArray(sess.files) ? sess.files : [],
        blocks: mappedBlocks.length > 0 ? mappedBlocks : [
          { id: Date.now(), name: isEn ? 'Warm-up' : 'Calentamiento', duration: 15, type: isEn ? 'Physical' : 'Física', description: '', imageUrl: null, imagenProtocolo: null }
        ],
        linkedPizarraId: String(sess.linkedPizarraId || ''),
      };

      console.log('[handleEditSession] EditData precargado exitosamente:', cleanEditData);
      setEditData(cleanEditData);
      setSelectedSession(null);
      setViewMode('edit');
      if (sess.id && !location.pathname.includes(`/sesiones/${sess.id}`)) {
        navigate(`/sesiones/${sess.id}`);
      }
      setTimeout(() => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }, 50);
    } catch (err) {
      console.error('[handleEditSession] Error al abrir formulario de edición:', err);
      showToast(isEn ? `Error opening editor: ${err.message || err}` : `Error al abrir editor: ${err.message || err}`, 'error');
    }
  };

  // Sincronización automática de URL con modo edición
  useEffect(() => {
    if (location.pathname.endsWith('/sesiones/nueva')) {
      if (viewMode !== 'edit' || (editData && editData.id)) {
        if (!isPro && sessions.length >= limits.SESSIONS) {
          setUpgradeModal({
            open: true,
            message: isEn
              ? `You have reached the limit of ${limits.SESSIONS} sessions on the free plan.`
              : `Has alcanzado el límite de ${limits.SESSIONS} sesiones del plan gratuito.`
          });
          return;
        }
        setEditData(initNewSessionData());
        setViewMode('edit');
      }
    } else if (urlSessionId && urlSessionId !== 'nueva') {
      if (!loadingSessions && sessions && sessions.length > 0) {
        const found = sessions.find(s => String(s.id) === String(urlSessionId));
        if (found && (!editData || String(editData.id) !== String(found.id))) {
          handleEditSession(found);
        }
      }
    }
  }, [location.pathname, urlSessionId, loadingSessions, sessions, initNewSessionData]);

  const handleDeleteSession = async (id) => {
    const confirmDelete = await showConfirm(isEn ? 'Confirm deletion' : 'Confirmar eliminación', isEn ? 'Delete this session?' : '¿Eliminar esta sesión?');
    if (confirmDelete) {
      try {
        const sessionToDelete = sessions.find(s => s.id === id);
        // Intentar borrar archivos de Storage si existen
        if (sessionToDelete?.files) {
          for (const file of sessionToDelete.files) {
            if (file.storagePath) {
              try {
                const fileRef = ref(storage, file.storagePath);
                await deleteObject(fileRef);
              } catch (e) { console.error("Error deleting file from storage:", e); }
            }
          }
        }
        await removeSession(id);
        if(selectedSession?.id === id) setSelectedSession(null);
      } catch (error) {
        await showAlert('Error', isEn ? 'Error deleting session.' : 'Error al eliminar sesión.');
      }
    }
  };

  const handleDeleteCapture = async (capture) => {
    const confirmDelete = await showConfirm(isEn ? 'Confirm deletion' : 'Confirmar eliminación', isEn ? 'Delete this capture?' : '¿Eliminar esta captura?');
    if (confirmDelete) {
      try {
        if (capture.storagePath) {
          try {
            const fileRef = ref(storage, capture.storagePath);
            await deleteObject(fileRef);
          } catch (e) {
            console.error("Error al borrar de Storage:", e);
          }
        }
        await removeCapture(capture.id);
        if(selectedCapture?.id === capture.id) setSelectedCapture(null);
      } catch (error) {
        console.error(error);
        await showAlert('Error', isEn ? 'Error deleting capture.' : 'Error al eliminar captura.');
      }
    }
  };

  const handleDeleteAnimation = async (anim) => {
    if (!anim) return;
    const confirmDelete = await showConfirm(isEn ? 'Confirm deletion' : 'Confirmar eliminación', isEn ? 'Permanently delete this animation?' : '¿Eliminar esta animación permanentemente?');
    if (confirmDelete) {
      try {
        if (user && activeTeamId) {
          const teamPath = getTeamPath();

          // 1. Borrar el video compilado de Storage (si existe y no es nulo)
          if (anim.videoUrl && anim.videoUrl.includes('firebasestorage.googleapis.com')) {
            try {
              const fileType = anim.videoMimeType && anim.videoMimeType.includes('mp4') ? 'mp4' : 'webm';
              const storagePath = `pizarras/${teamPath}/${anim.id}/video.${fileType}`;
              const videoRef = ref(storage, storagePath);
              await deleteObject(videoRef);
            } catch (storageErr) {
              console.warn('[handleDeleteAnimation] No se pudo eliminar el video de Storage (posiblemente no existía o expiró):', storageErr);
            }
          }

          // 2. Borrar subcolección de frames en Firestore (si existe y no es nula)
          try {
            const framesColRef = collection(db, teamPath, 'pizarras', anim.id, 'frames');
            const snap = await getDocs(framesColRef);
            if (snap && !snap.empty) {
              const batch = writeBatch(db);
              snap.docs.forEach(d => {
                batch.delete(d.ref);
              });
              await batch.commit();
            }
          } catch (framesErr) {
            console.error('[handleDeleteAnimation] Error al borrar frames de la animación:', framesErr);
          }

          // 3. Borrar el documento de la pizarra en Firestore
          try {
            const pizarraDocRef = doc(db, teamPath, 'pizarras', anim.id);
            await deleteDoc(pizarraDocRef);
          } catch (docErr) {
            console.error('[handleDeleteAnimation] Error al borrar documento pizarra:', docErr);
          }

          // 4. Limpiar almacenamiento local
          const lsKey = `mister11_last_pizarra_${activeTeamId}`;
          if (localStorage.getItem(lsKey) === anim.id) {
            localStorage.removeItem(lsKey);
          }
        }

        // 5. Eliminar la referencia en la colección de ejercicios
        try {
          await removeExercise(anim.id);
        } catch (exErr) {
          console.error('[handleDeleteAnimation] Error al borrar el ejercicio en Firestore:', exErr);
        }

        if (selectedAnimation && selectedAnimation.id === anim.id) {
          setSelectedAnimation(null);
        }
        showToast(isEn ? 'Animation deleted successfully' : 'Animación eliminada exitosamente', 'success');
      } catch (error) {
        console.error('Error general eliminando animación: ', error);
        await showAlert('Error', isEn ? 'Error deleting the animation.' : 'Error al eliminar la animación.');
      }
    }
  };

  // --- EDIT MODE FUNCTIONS ---

  /**
   * Convierte un dataURL Base64 a un objeto Blob
   */
  const dataURLtoBlob = (dataurl) => {
    if (!dataurl || typeof dataurl !== 'string' || !dataurl.startsWith('data:')) return null;
    try {
      const arr = dataurl.split(',');
      const mimeMatch = arr[0].match(/:(.*?);/);
      const mime = mimeMatch ? mimeMatch[1] : 'image/png';
      const bstr = atob(arr[1]);
      let n = bstr.length;
      const u8arr = new Uint8Array(n);
      while (n--) {
        u8arr[n] = bstr.charCodeAt(n);
      }
      return new Blob([u8arr], { type: mime });
    } catch (e) {
      console.error('[Sesiones] Error convirtiendo dataURL a Blob:', e);
      return null;
    }
  };

  /**
   * Procesa la imagen o captura adjunta a un bloque:
   * - Si ya es una URL pública HTTPS/HTTP, la mantiene.
   * - Si es un objeto File/Blob o una cadena base64 nueva, la sube a Firebase Storage y devuelve la URL pública.
   */
  const processBlockImage = async (block, index, sessionId) => {
    // Buscar la imagen en cualquiera de los nombres de campos posibles
    const rawImg = block.imageUrl || block.imagenProtocolo || block.image || block.photo || block.previewUrl || block.canvasData || null;
    const rawFile = block.file || block.imageFile || block.blob || null;

    // Si ya es una URL pública HTTPS/HTTP, la devolvemos intacta
    if (typeof rawImg === 'string' && rawImg.startsWith('http')) {
      console.log(`[Sesiones] Bloque ${index + 1} conserva URL existente:`, rawImg);
      return rawImg;
    }

    // Identificar el Blob o File que debe subirse
    let blobToUpload = null;
    if (rawFile && (rawFile instanceof File || rawFile instanceof Blob)) {
      blobToUpload = rawFile;
    } else if (typeof rawImg === 'string' && rawImg.startsWith('data:')) {
      blobToUpload = dataURLtoBlob(rawImg);
    }

    if (!blobToUpload) {
      return null;
    }

    // Subir a Firebase Storage
    try {
      const teamPath = getTeamPath(activeTeamId);
      const sid = sessionId || editData?.id || `session_${Date.now()}`;
      const ext = blobToUpload.type?.includes('jpeg') ? 'jpg' : 'png';
      const storagePath = `teams/${activeTeamId || 'default'}/sessions/${sid}/block_${index}_${Date.now()}.${ext}`;
      const storageRef = ref(storage, storagePath);

      await uploadBytesResumable(storageRef, blobToUpload);
      const downloadUrl = await getDownloadURL(storageRef);
      console.log(`[Sesiones] ✅ Imagen subida exitosamente para Bloque ${index + 1}:`, downloadUrl);
      return downloadUrl;
    } catch (err) {
      console.error(`[Sesiones] ❌ Error subiendo imagen de Bloque ${index + 1} a Storage:`, err);
      return null;
    }
  };

  const handleSaveSession = async () => {
    const title = (editData?.title || '').trim();
    if (!title) {
      await showAlert(isEn ? 'Validation' : 'Validación', isEn ? 'Session title is required.' : 'El título de la sesión es obligatorio.');
      return;
    }

    setIsSaving(true);
    try {
      const rawBlocks = editData.blocks || [];
      const sessionId = editData.id || null;

      // ── Paso 1: Procesar y subir todas las imágenes de los bloques en paralelo ──
      const updatedBlocks = await Promise.all(
        rawBlocks.map(async (b, idx) => {
          const imageUrl = await processBlockImage(b, idx, sessionId);
          return {
            id: b.id || `${Date.now()}_${idx}`,
            name: b.name || b.nombre || `Bloque ${idx + 1}`,
            duration: Number(b.duration || b.duracion) || 15,
            type: b.type || b.tipo || 'Táctica',
            description: b.description || b.descripcion || '',
            // Guardar explícitamente tanto en imageUrl como en imagenProtocolo para máxima compatibilidad
            imageUrl: imageUrl || null,
            imagenProtocolo: imageUrl || null,
            // Eliminar objetos local File/Blob que Firestore rechaza
            file: null,
            imageFile: null,
            blob: null
          };
        })
      );

      // ── Paso 2: Construir el payload con bloques actualizados ──
      const sessionPayload = {
        title,
        date: editData.date || new Date().toISOString().split('T')[0],
        time: editData.time || '18:00',
        category: editData.category || 'Táctica',
        intensity: editData.intensity || 'Media',
        duration: Number(editData.duration) || 90,
        players: Array.isArray(editData.players) ? editData.players : [],
        files: Array.isArray(editData.files) ? editData.files : [],
        objectives: editData.objectives || '',
        materials: editData.materials || '',
        linkedPizarraId: editData.linkedPizarraId || '',
        blocks: updatedBlocks
      };

      // ── Paso 3: Guardar en Firestore ──
      if (editData.id) {
        await updateSession(editData.id, sessionPayload);
        showToast(isEn ? 'Session updated successfully' : 'Sesión actualizada exitosamente', 'success');
        setSelectedSession({ ...sessionPayload, id: editData.id });
      } else {
        const newId = await addSession(sessionPayload);
        showToast(isEn ? 'Session saved successfully' : 'Sesión guardada exitosamente', 'success');
        if (newId) {
          setSelectedSession({ ...sessionPayload, id: newId });
        }
      }
      setViewMode('list');
      setEditData(null);
      if (location.pathname !== '/sesiones') {
        navigate('/sesiones');
      }
    } catch (error) {
      console.error('[Sesiones] Error al guardar sesión:', error);
      showToast(error?.message || (isEn ? 'Error saving the session' : 'Error al guardar la sesión'), 'error');
      await showAlert('Error', error?.message || (isEn ? 'Error saving the session to the database.' : 'Error al guardar la sesión en la base de datos.'));
    } finally {
      // SIEMPRE liberar el estado de carga
      setIsSaving(false);
    }
  };

  const handleAddBlock = () => {
    setEditData(prev => ({
      ...prev,
      blocks: [...prev.blocks, { id: Date.now() + Math.random(), name: isEn ? 'New Exercise' : 'Nuevo Ejercicio', duration: 15, type: isEn ? 'Tactical' : 'Táctica', description: '' }]
    }));
  };

  const handleUpdateBlock = (blockId, field, value) => {
    setEditData(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => b.id === blockId ? { ...b, [field]: value } : b)
    }));
  };

  const handleDeleteBlock = (blockId) => {
    setEditData(prev => ({
      ...prev,
      blocks: prev.blocks.filter(b => b.id !== blockId)
    }));
  };

  const handleDuplicateBlock = (block) => {
    const duplicate = { ...block, id: Date.now() + Math.random(), name: `${block.name} (${isEn ? 'copy' : 'copia'})` };
    setEditData(prev => {
      const idx = prev.blocks.findIndex(b => b.id === block.id);
      const newBlocks = [...prev.blocks];
      newBlocks.splice(idx + 1, 0, duplicate);
      return { ...prev, blocks: newBlocks };
    });
  };

  const handleMoveBlock = (index, direction) => {
    setEditData(prev => {
      const newIndex = index + direction;
      if (newIndex < 0 || newIndex >= prev.blocks.length) return prev;
      const newBlocks = [...prev.blocks];
      const [movedBlock] = newBlocks.splice(index, 1);
      newBlocks.splice(newIndex, 0, movedBlock);
      return { ...prev, blocks: newBlocks };
    });
  };

  const handleTogglePlayer = (playerId) => {
    setEditData(prev => {
      const has = prev.players.includes(playerId);
      return {
        ...prev,
        players: has ? prev.players.filter(id => id !== playerId) : [...prev.players, playerId]
      };
    });
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file || !user || !activeTeamId) return;
    
    if (file.type !== 'application/pdf') {
      await showAlert(isEn ? 'Validation' : 'Validación', isEn ? 'Only PDF files are allowed.' : 'Solo se permiten archivos PDF.');
      return;
    }

    setIsSaving(true);
    const sessionId = editData.id || `temp_${Date.now()}`;
    const storagePath = `sessions/${getTeamPath()}/${sessionId}/${file.name}`;
    const fileRef = ref(storage, storagePath);
    
    const uploadTask = uploadBytesResumable(fileRef, file);

    uploadTask.on('state_changed',
      (snapshot) => {
        const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        setUploadProgress(progress);
      },
      async (error) => {
        console.error("Error uploading file:", error);
        await showAlert('Error', isEn ? 'Error uploading the file. Check your connection.' : 'Error al subir el archivo. Revisa tu conexión.');
        setIsSaving(false);
        setUploadProgress(0);
      },
      async () => {
        const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
        const newFile = {
          id: Date.now(),
          name: file.name,
          size: (file.size / 1024 / 1024).toFixed(2) + ' MB',
          type: file.type,
          url: downloadURL,
          storagePath: storagePath
        };

        setEditData(prev => ({
          ...prev,
          files: [...prev.files, newFile]
        }));
        setIsSaving(false);
        setUploadProgress(0);
      }
    );
  };

  const handleRemoveFile = async (fileId) => {
    const fileToRemove = editData.files.find(f => f.id === fileId);
    if (fileToRemove?.storagePath) {
      try {
        const fileRef = ref(storage, fileToRemove.storagePath);
        await deleteObject(fileRef);
      } catch (e) { console.error("Error deleting file:", e); }
    }
    setEditData(prev => ({
      ...prev,
      files: prev.files.filter(f => f.id !== fileId)
    }));
  };

  if (loadingSessions || loadingPlayers || loadingCaptures || loadingExercises) {
    return (
      <div className="page-wrapper" style={{ padding: '24px' }}>
        <header className="page-header">
          <div className="skeleton-line" style={{ width: '180px', height: '32px', marginBottom: '12px' }}></div>
          <div className="skeleton-line" style={{ width: '280px', height: '18px' }}></div>
        </header>
        <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', paddingBottom: '8px', marginBottom: '20px' }}>
          {[1, 2, 3, 4, 5, 6, 7].map(n => (
            <div key={n} className="skeleton-line" style={{ width: '50px', height: '60px', borderRadius: '8px' }}></div>
          ))}
        </div>
        <div className="grid-3-cols" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '24px' }}>
          {[1, 2, 3].map(n => (
            <div key={n} className="skeleton-card" style={{ height: '220px', borderRadius: '16px' }}></div>
          ))}
        </div>
      </div>
    );
  }

  // --- RENDER EDIT MODE ---
  if (viewMode === 'edit' && editData) {
    return (
      <div className="sesiones-page session-editor-page">
        <header className="sesiones-header edit-mode-header">
          <div className="header-top">
            <div className="title-group">
              <button
                type="button"
                className="btn-icon-back"
                onClick={handleBackToList}
              >
                ← {t('common.back')}
              </button>
              <h1 className="session-editor-title" title={editData.title || (isEn ? 'New Session' : 'Nueva Sesión')}>
                {editData.title || (isEn ? 'New Session' : 'Nueva Sesión')}
              </h1>
            </div>
            <div className="sesiones-page-actions desktop-only-actions">
              <button
                type="button"
                className="btn-outline btn-session-cancel"
                onClick={handleBackToList}
              >
                {t('common.cancel')}
              </button>
              <button
                type="button"
                className="btn-primary btn-session-save"
                onClick={handleSaveSession}
                disabled={isSaving}
              >
                {isSaving ? t('common.saving') : (isEn ? 'Save Session' : 'Guardar Sesión')}
              </button>
            </div>
          </div>
        </header>

        <div className="editor-content">
          <div className="editor-left">
            <div className="edit-section">
              <h3>{isEn ? 'General Data' : 'Datos Generales'}</h3>
              <div className="form-group full">
                <label>{isEn ? 'Session Title' : 'Título de la Sesión'}</label>
                <SpellCheckedInput value={editData.title} onChange={e => setEditData({...editData, title: e.target.value})} onBlur={e => setEditData(prev => ({...prev, title: normalizeText(e.target.value)}))} placeholder={isEn ? 'e.g. Activation and Rondo...' : 'Ej. Activación y Rondo...'} />
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>{isEn ? 'Date' : 'Fecha'}</label>
                  <input type="date" value={editData.date} onChange={e => setEditData({...editData, date: e.target.value})} />
                </div>
                <div className="form-group">
                  <label>{isEn ? 'Time' : 'Hora'}</label>
                  <input type="time" value={editData.time} onChange={e => setEditData({...editData, time: e.target.value})} />
                </div>
                <div className="form-group">
                  <label>{isEn ? 'Duration (min)' : 'Duración (min)'}</label>
                  <input type="number" min="15" step="5" value={editData.duration} onChange={e => setEditData({...editData, duration: Number(e.target.value)})} />
                </div>
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>{isEn ? 'Category' : 'Categoría'}</label>
                  <select value={editData.category} onChange={e => setEditData({...editData, category: e.target.value})}>
                    <option value="Técnica">{isEn ? 'Technical' : 'Técnica'}</option>
                    <option value="Táctica">{isEn ? 'Tactical' : 'Táctica'}</option>
                    <option value="Física">{isEn ? 'Physical' : 'Física'}</option>
                    <option value="Mixta">{isEn ? 'Mixed' : 'Mixta'}</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>{isEn ? 'Intensity / Load' : 'Intensidad / Carga'}</label>
                  <select value={editData.intensity} onChange={e => setEditData({...editData, intensity: e.target.value})}>
                    <option value="Baja">{isEn ? 'Low (Recovery)' : 'Baja (Recuperación)'}</option>
                    <option value="Media">{isEn ? 'Medium (Maintenance)' : 'Media (Mantenimiento)'}</option>
                    <option value="Alta">{isEn ? 'High (Acquisition)' : 'Alta (Adquisición)'}</option>
                    <option value="Máxima">{isEn ? 'Maximum (Competition)' : 'Máxima (Competición)'}</option>
                  </select>
                </div>
              </div>
              <div className="form-group full" style={{marginTop: '16px'}}>
                <label>{isEn ? 'Main Objective' : 'Objetivo Principal'}</label>
                <SpellCheckedTextarea value={editData.objectives || ''} onChange={e => setEditData({...editData, objectives: e.target.value})} placeholder={isEn ? 'e.g. Improve ball circulation in the build-up zone...' : 'Ej. Mejorar la circulación del balón en zona de creación...'} rows={2} style={{minHeight: '60px'}} />
              </div>
              <div className="form-group full">
                <label>{isEn ? 'Required Equipment' : 'Material Necesario'}</label>
                <input type="text" value={editData.materials || ''} onChange={e => setEditData({...editData, materials: e.target.value})} onBlur={e => setEditData(prev => ({...prev, materials: normalizeText(e.target.value)}))} placeholder={isEn ? 'e.g. 10 balls, 15 bibs (red/blue), 20 cones' : 'Ej. 10 balones, 15 petos (rojos/azules), 20 conos'} />
              </div>
              <div className="form-group full" style={{marginTop: '16px'}}>
                <label>{isEn ? '🎬 Link Animation / Tactical Board' : '🎬 Vincular Animación / Pizarra Táctica'}</label>
                <select 
                  value={editData.linkedPizarraId || ''} 
                  onChange={e => setEditData({...editData, linkedPizarraId: e.target.value})}
                  className="theme-select-mister11"
                  style={{
                    width: '100%',
                    padding: '10px 12px',
                    borderRadius: '8px',
                    border: '1.5px solid var(--border-color)',
                    background: 'var(--input-bg)',
                    color: 'var(--input-text)',
                    fontSize: '14px',
                    outline: 'none',
                    marginTop: '4px'
                  }}
                >
                  <option value="">{isEn ? 'No linked animation' : 'Ninguna animación vinculada'}</option>
                  {pizarras.map(piz => (
                    <option key={piz.id} value={piz.id}>{piz.title || (isEn ? 'Untitled' : 'Sin Título')}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="edit-section">
              <div className="section-header-flex">
                <h3>{isEn ? 'Attached Files (PDF)' : 'Archivos Adjuntos (PDF)'}</h3>
                <button className="btn-small-outline" onClick={() => fileInputRef.current?.click()} disabled={uploadProgress > 0 && uploadProgress < 100}>+ {isEn ? 'Upload PDF' : 'Subir PDF'}</button>
                <input type="file" ref={fileInputRef} style={{display:'none'}} accept=".pdf" onChange={handleFileUpload} />
              </div>
              {uploadProgress > 0 && uploadProgress < 100 && (
                <div style={{width: '100%', height: '8px', background: '#e0e0e0', borderRadius: '4px', margin: '10px 0', overflow: 'hidden'}}>
                  <div style={{width: `${uploadProgress}%`, height: '100%', background: 'var(--accent)', transition: 'width 0.3s ease'}}></div>
                </div>
              )}
              {editData.files.length === 0 ? (
                <div className="empty-files">{isEn ? 'No attached files. Upload a PDF with diagrams or notes.' : 'No hay archivos adjuntos. Sube un PDF con diagramas o apuntes.'}</div>
              ) : (
                <div className="files-list">
                  {editData.files.map(f => (
                    <div key={f.id} className="file-item">
                      <span className="file-icon">📄</span>
                      <div className="file-info">
                        <span className="file-name">{f.name}</span>
                        <span className="file-size">{f.size}</span>
                      </div>
                      {f.url && <button className="btn-small-outline" style={{marginRight: '10px'}} onClick={() => setPdfPreview(f.url)}>{t('sesiones.preview.viewPdf')}</button>}
                      <button className="btn-del-icon" onClick={() => handleRemoveFile(f.id)}>✕</button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="edit-section">
              <div className="section-header-flex">
                <h3>{isEn ? `Squad List (${editData.players.length}/${players.length})` : `Convocatoria (${editData.players.length}/${players.length})`}</h3>
                <button className="btn-text" onClick={() => setEditData({...editData, players: players.map(p=>p.id)})}>{isEn ? 'Select All' : 'Marcar Todos'}</button>
              </div>
              <div className="players-checklist">
                {players.map(p => (
                  <label key={p.id} className={`player-check-item ${editData.players.includes(p.id) ? 'selected' : ''}`}>
                    <input type="checkbox" checked={editData.players.includes(p.id)} onChange={() => handleTogglePlayer(p.id)} />
                    <span className="p-num">{p.number}</span>
                    <span className="p-name">{p.name}</span>
                  </label>
                ))}
              </div>
            </div>
          </div>

          <div className="editor-right">
            <div className="blocks-header">
              <h3>{isEn ? 'Session Format' : 'Formato de la Sesión'}</h3>
              <button className="btn-primary-small" onClick={handleAddBlock}>{t('sesiones.preview.addBlock')}</button>
            </div>
            
            <div className="blocks-builder-list">
              {editData.blocks.length === 0 ? (
                <div className="empty-blocks">{isEn ? 'Add training blocks to organise your session.' : 'Añade bloques de entrenamiento para organizar tu sesión.'}</div>
              ) : (
                <DndContext
                  sensors={sensors}
                  collisionDetection={closestCenter}
                  onDragEnd={handleDragEnd}
                >
                  <SortableContext
                    items={editData.blocks.map(b => b.id)}
                    strategy={verticalListSortingStrategy}
                  >
                    {editData.blocks.map((block, index) => (
                      <BlockEditor
                        key={block.id}
                        block={block}
                        index={index}
                        totalBlocks={editData.blocks.length}
                        handleUpdateBlock={handleUpdateBlock}
                        handleDeleteBlock={handleDeleteBlock}
                        handleDuplicateBlock={handleDuplicateBlock}
                        handleMoveBlock={handleMoveBlock}
                        teamId={activeTeam?.id}
                        sessionId={editData?.id}
                      />
                    ))}
                  </SortableContext>
                </DndContext>
              )}
            </div>
          </div>
        </div>

        {/* Barra fija inferior de acciones para móvil <600px: Cancelar (40%) y Guardar (60%) renderizada vía createPortal */}
        {typeof document !== 'undefined' ? createPortal(
          <div className="session-editor-bottom-bar" id="session-editor-bottom-bar-portal">
            <button
              type="button"
              className="btn-outline btn-session-cancel"
              onClick={handleBackToList}
              data-testid="session-cancel-btn"
            >
              {t('common.cancel')}
            </button>
            <button
              type="button"
              className="btn-primary btn-session-save"
              onClick={handleSaveSession}
              disabled={isSaving}
              data-testid="session-save-btn"
            >
              {isSaving ? t('common.saving') : (isEn ? 'Save Session' : 'Guardar Sesión')}
            </button>
          </div>,
          document.body
        ) : null}

        {/* PDF PREVIEW MODAL */}
        {pdfPreview && (
          <div className="modal-overlay-pdf" onClick={() => setPdfPreview(null)}>
            <div className="modal-content-pdf" onClick={e => e.stopPropagation()}>
              <div className="modal-header-pdf">
                <h3>{isEn ? 'PDF Preview' : 'Vista Previa del PDF'}</h3>
                <button className="btn-close-pdf" onClick={() => setPdfPreview(null)}>✕</button>
              </div>
              <div className="modal-body-pdf">
                <iframe src={pdfPreview} title={isEn ? "PDF Preview" : "Vista Previa del PDF"} width="100%" height="100%" style={{border: 'none'}}></iframe>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- RENDER LIST MODE ---
  return (
    <div className="page-wrapper">
      <header className="page-header">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px', flexWrap: 'wrap', gap: '16px' }}>
          <h1 className="page-title" style={{ margin: 0 }}>{t('sesiones.title')}</h1>
          <div className="sesiones-top-actions-bar" style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
            <button className={`tab-switcher ${activeTab === 'sessions' ? 'active' : ''}`} onClick={() => setActiveTab('sessions')} style={{ width: 'auto', flex: '0 0 auto', whiteSpace: 'nowrap' }}>{t('sesiones.tab.sessions')}</button>
            <button className={`tab-switcher ${activeTab === 'captures' ? 'active' : ''}`} onClick={() => setActiveTab('captures')} style={{ width: 'auto', flex: '0 0 auto', whiteSpace: 'nowrap' }}>{t('sesiones.tab.captures')}</button>
            <button className={`tab-switcher ${activeTab === 'animations' ? 'active' : ''}`} onClick={() => setActiveTab('animations')} style={{ width: 'auto', flex: '0 0 auto', whiteSpace: 'nowrap' }}>{t('sesiones.tab.animations')}</button>
            <div style={{ width: '1px', height: '24px', background: 'var(--border-light)', margin: '0 8px', flexShrink: 0 }} />
            <button
              className="btn-outline-gold"
              onClick={() => {
                if (sessions.length > 0) {
                  setSelectedSession(sessions[0]);
                  setShowLiveField(true);
                } else {
                  showToast(isEn ? 'No sessions available.' : 'No hay sesiones disponibles.', 'info');
                }
              }}
              style={{ padding: '8px 16px', minHeight: '44px', width: 'auto', flex: '0 0 auto', whiteSpace: 'nowrap', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '6px', fontWeight: 'bold' }}
            >
              ⏱️ {t('sesiones.fieldMode')}
            </button>
            <button
              className="btn-outline-gold"
              onClick={() => setImportModal({ open: true, activeTab: 'link', inputVal: '', loading: false, previewSession: null, file: null, error: '' })}
              style={{ padding: '8px 16px', minHeight: '44px', width: 'auto', flex: '0 0 auto', whiteSpace: 'nowrap', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '6px', fontWeight: 'bold' }}
            >
              📥 {t('sesiones.importSession')}
            </button>
            {activeTab === 'sessions' && sessions.length > 0 && (
              <button 
                className="btn-outline-gold" 
                onClick={handleExportAllSessionsICS}
                style={{ padding: '8px 16px', minHeight: '44px', width: 'auto', flex: '0 0 auto', whiteSpace: 'nowrap', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '6px', fontWeight: 'bold' }}
              >
                {t('sesiones.exportICS')}
              </button>
            )}
            <button className="btn-primary-new" onClick={handleCreateNew} style={{ width: 'auto', flex: '0 0 auto', whiteSpace: 'nowrap' }}>{t('sesiones.newSession')}</button>
          </div>
        </div>

        {/* FASE 5: Barra Switcher DÍA | SEMANA | MES */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px', flexWrap: 'wrap', gap: '10px' }}>
          <div className="calendar-view-switcher" style={{ display: 'inline-flex', background: 'var(--bg-card)', border: '1.5px solid var(--border-light)', borderRadius: '10px', padding: '3px', gap: '4px' }}>
            {[
              { id: 'dia', label: t('sesiones.views.day') },
              { id: 'semana', label: t('sesiones.views.week') },
              { id: 'mes', label: t('sesiones.views.month') }
            ].map(v => (
              <button
                key={v.id}
                type="button"
                className={`cal-view-btn ${calendarView === v.id ? 'active' : ''}`}
                onClick={() => setCalendarView(v.id)}
                style={{
                  padding: '6px 14px',
                  borderRadius: '7px',
                  border: 'none',
                  fontSize: '11px',
                  fontWeight: 900,
                  cursor: 'pointer',
                  background: calendarView === v.id ? 'var(--accent-gold)' : 'transparent',
                  color: calendarView === v.id ? '#000000' : 'var(--text-secondary)',
                  transition: 'all 0.15s'
                }}
              >
                {v.label}
              </button>
            ))}
          </div>

          {/* Indicador de Leyenda de Puntos */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', fontSize: '11px', color: 'var(--text-secondary)' }}>
            <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}><span style={{ width: 7, height: 7, borderRadius: '50%', background: '#3B82F6' }}></span> {t('sesiones.categories.tecnica')}</span>
            <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}><span style={{ width: 7, height: 7, borderRadius: '50%', background: '#10B981' }}></span> {t('sesiones.categories.tactica')}</span>
            <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}><span style={{ width: 7, height: 7, borderRadius: '50%', background: '#F97316' }}></span> {t('sesiones.categories.fisica')}</span>
            <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}><span style={{ width: 7, height: 7, borderRadius: '50%', background: '#A855F7' }}></span> {t('sesiones.categories.mixta')}</span>
            <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}><span style={{ width: 7, height: 7, borderRadius: '50%', background: '#D4A843' }}></span> {t('sesiones.categories.partido')}</span>
          </div>
        </div>

        {/* Vista SEMANA o DÍA: Tiras de días con puntos de contenido */}
        {calendarView !== 'mes' && (
          <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', paddingBottom: '8px', marginBottom: '16px' }}>
            {(() => {
              const today = new Date();
              const currentDay = today.getDay(); // 0 (Sun) to 6 (Sat)
              const diff = today.getDate() - currentDay + (currentDay === 0 ? -6 : 1);
              const monday = new Date(new Date().setDate(diff));
              const narrowWeekdays = getWeekdays('narrow', true);
              
              return narrowWeekdays.map((day, i) => {
                const date = new Date(monday);
                date.setDate(monday.getDate() + i);
                const y = date.getFullYear();
                const m = String(date.getMonth() + 1).padStart(2, '0');
                const d = String(date.getDate()).padStart(2, '0');
                const dateStr = `${y}-${m}-${d}`;
                const isSelected = selectedCalendarDate === dateStr;
                const isToday = date.toDateString() === new Date().toDateString();
                const daySessions = getSessionsForDate(date);

                return (
                  <div
                    key={i}
                    className={`chip-gold ${isSelected ? 'active' : ''}`}
                    onClick={() => {
                      setSelectedCalendarDate(dateStr);
                      if (calendarView === 'dia') {
                        // filteredSessions updates automatically
                      }
                    }}
                    style={{
                      cursor: 'pointer',
                      minWidth: '54px',
                      padding: '8px 6px',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      background: isSelected ? 'var(--accent-gold)' : (isToday ? 'rgba(212,168,67,0.15)' : 'var(--bg-card)'),
                      border: `1.5px solid ${isSelected ? 'var(--accent-gold)' : (isToday ? 'rgba(212,168,67,0.4)' : 'var(--border-light)')}`,
                      borderRadius: '12px'
                    }}
                  >
                    <span style={{ fontSize: '11px', opacity: isSelected ? 1 : 0.7, fontWeight: 700 }}>{day}</span>
                    <strong style={{ fontSize: '16px', color: isSelected ? '#000000' : 'inherit' }}>{date.getDate()}</strong>
                    {/* Puntos de contenido por sesión */}
                    <div style={{ display: 'flex', gap: '3px', marginTop: '4px', minHeight: '6px' }}>
                      {daySessions.map((s, sIdx) => {
                        const col = CATEGORY_COLORS[s?.category || s?.categoria] || '#6B7280';
                        return <span key={s?.id || sIdx} style={{ width: 6, height: 6, borderRadius: '50%', background: col }}></span>;
                      })}
                    </div>
                  </div>
                );
              });
            })()}
          </div>
        )}

        {/* Vista MES: Cuadrícula Mensual L-D Mobile First */}
        {calendarView === 'mes' && (
          <div className="month-calendar-container" style={{ background: 'var(--bg-card)', border: '1px solid var(--border-light)', borderRadius: '16px', padding: '16px', marginBottom: '18px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '14px' }}>
              <strong style={{ fontSize: '15px', color: 'var(--text-primary)', textTransform: 'uppercase' }}>
                {new Date().toLocaleDateString(locale, { month: 'long', year: 'numeric' })}
              </strong>
              <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{t('sesiones.clickDayToView')}</span>
            </div>
            {/* Header L-D */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', textAlign: 'center', fontSize: '11px', fontWeight: 900, color: 'var(--text-secondary)', marginBottom: '8px' }}>
              {getWeekdays('short', true).map(d => <span key={d}>{d.toUpperCase()}</span>)}
            </div>
            {/* Celdas del mes actual */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '6px' }}>
              {(() => {
                const now = new Date();
                const year = now.getFullYear();
                const month = now.getMonth();
                const firstDay = new Date(year, month, 1);
                const lastDay = new Date(year, month + 1, 0);
                const daysInMonth = lastDay.getDate();
                // Ajustar primer día a lunes (0=domingo -> 6, 1=lunes -> 0)
                const startOffset = (firstDay.getDay() + 6) % 7;

                const cells = [];
                for (let i = 0; i < startOffset; i++) {
                  cells.push(<div key={`empty-${i}`} style={{ minHeight: '44px', opacity: 0.2 }}></div>);
                }
                for (let dayNum = 1; dayNum <= daysInMonth; dayNum++) {
                  const dObj = new Date(year, month, dayNum);
                  const mStr = String(month + 1).padStart(2, '0');
                  const dayStr = String(dayNum).padStart(2, '0');
                  const dateStr = `${year}-${mStr}-${dayStr}`;
                  const isSelected = selectedCalendarDate === dateStr;
                  const isToday = dObj.toDateString() === new Date().toDateString();
                  const daySessions = getSessionsForDate(dObj);

                  cells.push(
                    <button
                      key={dayNum}
                      type="button"
                      onClick={() => {
                        setSelectedCalendarDate(dateStr);
                        setMonthBottomSheetOpen(true);
                      }}
                      style={{
                        minHeight: '46px',
                        padding: '4px',
                        borderRadius: '10px',
                        border: `1.5px solid ${isSelected ? 'var(--accent-gold)' : (isToday ? 'rgba(212,168,67,0.4)' : 'var(--border-light)')}`,
                        background: isSelected ? 'rgba(212,168,67,0.2)' : (isToday ? 'rgba(212,168,67,0.08)' : 'transparent'),
                        cursor: 'pointer',
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        color: 'inherit'
                      }}
                    >
                      <span style={{ fontSize: '12px', fontWeight: isToday ? 900 : 700, color: isToday ? 'var(--accent-gold)' : 'inherit' }}>{dayNum}</span>
                      <div style={{ display: 'flex', gap: '2px', flexWrap: 'wrap', justifyContent: 'center' }}>
                        {daySessions.map((s, sIdx) => {
                          const col = CATEGORY_COLORS[s.category || s.categoria] || '#6B7280';
                          return <span key={sIdx} style={{ width: 6, height: 6, borderRadius: '50%', background: col }}></span>;
                        })}
                      </div>
                    </button>
                  );
                }
                return cells;
              })()}
            </div>
          </div>
        )}

        {activeTab === 'sessions' && (
          <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', paddingBottom: '8px' }}>
            {categoryFilters.map(cat => (
              <button 
                key={cat.key} 
                className={`chip ${catFilter === cat.key ? 'active' : ''}`}
                onClick={() => setCatFilter(cat.key)}
              >
                {t(cat.labelKey)}
              </button>
            ))}
          </div>
        )}
      </header>

      {activeTab === 'sessions' ? (
        <div className="sessions-content">
          <div className="grid-3-cols">
            {filteredSessions.map(session => {
              const title      = session.title    || session.titulo    || (isEn ? 'Untitled' : 'Sin título');
              const time       = session.time     || session.hora      || '--:--';
              const duration   = session.duration || session.duracion  || 0;
              const category   = session.category || session.categoria || 'General';
              const intensity  = session.intensity|| session.intensidad|| 'Media';
              const blocks     = session.blocks   || session.bloques   || [];
              const linkedPiz = session.linkedPizarraId ? pizarras.find(p => p.id === session.linkedPizarraId) : null;
              const firstBlockWithImg = blocks.find(b => b.imagenProtocolo);
              const fallbackImage = firstBlockWithImg ? firstBlockWithImg.imagenProtocolo : null;
              
              return (
                <div key={session.id} className="card-base" style={{ padding: '0', cursor: 'pointer', display: 'flex', flexDirection: 'column', height: '100%' }} onClick={() => setSelectedSession(session)}>
                  <div style={{ padding: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid var(--border-light)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                      <span style={{ background: 'var(--accent-green-light)', color: 'var(--accent-green)', padding: '4px 12px', borderRadius: '16px', fontSize: '12px', fontWeight: 'bold' }}>{time}</span>
                      <span style={{ fontSize: '13px', color: 'var(--text-secondary)', fontWeight: 'bold' }}>{duration} min</span>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <GatedFeature feature="sessions" teamContext={activeTeamId} silent={true}>
                        <button
                          type="button"
                          onClick={(e) => { e.stopPropagation(); setRatingModalSession(session); }}
                          style={{ background: 'rgba(212, 168, 67, 0.15)', border: '1px solid var(--accent-gold)', color: 'var(--accent-gold)', padding: '4px 10px', borderRadius: '12px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px' }}
                          title={isEn ? 'Rate players' : 'Calificar jugadores'}
                        >
                          <Star size={13} color="#D4A843" fill="#D4A843" /> {t('sessionRating.rateButton')}
                        </button>
                      </GatedFeature>
                      <button
                        type="button"
                        onClick={(e) => { e.stopPropagation(); handleEditSession(session); }}
                        style={{ background: 'rgba(255, 255, 255, 0.08)', border: '1px solid var(--border-light)', color: 'var(--text-primary)', padding: '4px 10px', borderRadius: '12px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px' }}
                        title={isEn ? 'Edit this session' : 'Editar esta sesión'}
                      >
                        ✏️ {t('sesiones.actions.edit')}
                      </button>
                      <button
                        type="button"
                        onClick={(e) => { e.stopPropagation(); handleShareSession(session); }}
                        style={{ background: 'rgba(212, 168, 67, 0.15)', border: '1px solid var(--accent-gold)', color: 'var(--accent-gold)', padding: '4px 10px', borderRadius: '12px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px' }}
                        title={isEn ? 'Share session with another coach' : 'Compartir sesión con otro entrenador'}
                      >
                        <Share2 size={13} /> {t('sesiones.actions.share')}
                      </button>
                    </div>
                  </div>
                  
                  <div style={{ padding: '16px', flex: 1, display: 'flex', flexDirection: 'column' }}>
                    <h3 style={{ margin: '0 0 16px 0', fontSize: '18px', fontFamily: 'var(--font-heading)', color: 'var(--text-primary)' }}>{title}</h3>
                    <div style={{ display: 'flex', gap: '12px', flex: 1 }}>
                      <div style={{ flex: 1, background: 'var(--bg-app)', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden', border: '1px solid var(--border-light)', position: 'relative', minHeight: '130px' }}>
                        {linkedPiz && linkedPiz.thumbnail ? (
                          <img src={linkedPiz.thumbnail} alt="Diagrama" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                        ) : fallbackImage ? (
                          <img src={fallbackImage} alt="Diagrama de Bloque" style={{ width: '100%', height: '100%', objectFit: 'contain', padding: '4px' }} />
                        ) : (
                          <span style={{ color: 'var(--text-secondary)', fontSize: '12px', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                            <svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" strokeWidth="2" fill="none"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><circle cx="8.5" cy="8.5" r="1.5"></circle><polyline points="21 15 16 10 5 21"></polyline></svg>
                            {t('sesiones.noDiagram')}
                          </span>
                        )}
                      </div>
                      
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', minWidth: '110px' }}>
                        <span style={{ fontSize: '11px', fontWeight: 'bold', background: 'var(--bg-card)', border: '1px solid var(--border-light)', padding: '8px', borderRadius: '8px', color: 'var(--text-primary)', textAlign: 'center', boxShadow: '0 1px 2px rgba(0,0,0,0.02)' }}>{category}</span>
                        <span style={{ fontSize: '11px', fontWeight: 'bold', background: 'var(--bg-card)', border: '1px solid var(--border-light)', padding: '8px', borderRadius: '8px', color: 'var(--text-primary)', textAlign: 'center', boxShadow: '0 1px 2px rgba(0,0,0,0.02)' }}>{intensity}</span>
                        <span style={{ fontSize: '11px', fontWeight: 'bold', background: 'var(--bg-card)', border: '1px solid var(--border-light)', padding: '8px', borderRadius: '8px', color: 'var(--text-primary)', textAlign: 'center', boxShadow: '0 1px 2px rgba(0,0,0,0.02)' }}>{fmtPlural(blocks.length, 'sesiones.blockCount')}</span>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
            {filteredSessions.length === 0 && (
              <div className="empty-state-list">{isEn ? 'No sessions in this category.' : 'No hay sesiones en esta categoría.'}</div>
            )}
          </div>

          {/* MONTH VIEW BOTTOM SHEET (Mobile / Tablet) */}
          {monthBottomSheetOpen && selectedCalendarDate && (
            <div className="event-selector-overlay" onClick={() => setMonthBottomSheetOpen(false)} style={{ zIndex: 99999 }}>
              <div
                className="sesiones-bottom-sheet"
                onClick={e => e.stopPropagation()}
                style={{
                  position: 'fixed',
                  bottom: 0,
                  left: 0,
                  right: 0,
                  background: 'var(--bg-card)',
                  borderTop: '2px solid var(--accent-gold)',
                  borderRadius: '20px 20px 0 0',
                  padding: '20px',
                  maxHeight: '75vh',
                  overflowY: 'auto',
                  boxShadow: '0 -10px 30px rgba(0,0,0,0.4)',
                  zIndex: 100000,
                  maxWidth: '680px',
                  margin: '0 auto'
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '14px', borderBottom: '1px solid var(--border-light)', paddingBottom: '10px' }}>
                  <div>
                    <span style={{ fontSize: '11px', color: 'var(--accent-gold)', fontWeight: 800, textTransform: 'uppercase' }}>📅 {isEn ? 'Daily Planning' : 'Planificación Diaria'}</span>
                    <h3 style={{ margin: '2px 0 0', fontSize: '18px', color: 'var(--text-primary)' }}>
                      {isEn ? `Sessions for ${selectedCalendarDate}` : `Sesiones del ${selectedCalendarDate}`}
                    </h3>
                  </div>
                  <button
                    type="button"
                    onClick={() => setMonthBottomSheetOpen(false)}
                    style={{ background: 'rgba(255,255,255,0.1)', border: 'none', color: 'var(--text-primary)', borderRadius: '8px', padding: '6px 12px', fontSize: '14px', fontWeight: 800, cursor: 'pointer' }}
                  >✕</button>
                </div>

                {(() => {
                  const daySessions = (sessions || []).filter(s => s && (s.date === selectedCalendarDate || s.fecha === selectedCalendarDate));
                  if (daySessions.length === 0) {
                    return (
                      <div style={{ textAlign: 'center', padding: '24px 10px', color: 'var(--text-secondary)' }}>
                        <div style={{ fontSize: '32px', marginBottom: '8px' }}>📋</div>
                        <p style={{ margin: '0 0 16px', fontSize: '14px' }}>{isEn ? 'No sessions scheduled for this day.' : 'No hay sesiones programadas para este día.'}</p>
                        <button
                          type="button"
                          className="btn-primary-new"
                          onClick={() => {
                            setMonthBottomSheetOpen(false);
                            handleCreateNew();
                          }}
                          style={{ margin: '0 auto', display: 'inline-flex' }}
                        >
                          + {isEn ? 'Create Session for this day' : 'Crear Sesión para este día'}
                        </button>
                      </div>
                    );
                  }

                  return (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                      {daySessions.map(session => {
                        const col = CATEGORY_COLORS[session.category || session.categoria] || '#6B7280';
                        return (
                          <div
                            key={session.id}
                            style={{
                              background: 'var(--bg-app)',
                              border: '1px solid var(--border-light)',
                              borderLeft: `4px solid ${col}`,
                              borderRadius: '12px',
                              padding: '12px 14px',
                              display: 'flex',
                              justifyContent: 'space-between',
                              alignItems: 'center',
                              gap: '12px'
                            }}
                          >
                            <div style={{ flex: 1 }}>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                                <span style={{ fontSize: '10px', fontWeight: 900, background: `${col}25`, color: col, padding: '2px 8px', borderRadius: '6px', textTransform: 'uppercase' }}>
                                  {session.category || session.categoria || 'General'}
                                </span>
                                <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                                  {session.duration || session.duracion || 90} min · {session.time || session.hora || '18:00'}
                                </span>
                              </div>
                              <strong style={{ fontSize: '14px', color: 'var(--text-primary)' }}>
                                {session.title || session.titulo || (isEn ? 'Untitled' : 'Sin título')}
                              </strong>
                            </div>

                            <div style={{ display: 'flex', gap: '6px' }}>
                              <button
                                type="button"
                                onClick={() => {
                                  setMonthBottomSheetOpen(false);
                                  setSelectedSession(session);
                                }}
                                style={{ padding: '6px 12px', borderRadius: '8px', border: '1px solid var(--border-light)', background: 'var(--bg-card)', color: 'var(--text-primary)', fontSize: '12px', fontWeight: 700, cursor: 'pointer' }}
                              >
                                {isEn ? 'View' : 'Ver'}
                              </button>
                              <button
                                type="button"
                                onClick={() => {
                                  setMonthBottomSheetOpen(false);
                                  handleEditSession(session);
                                }}
                                style={{ padding: '6px 12px', borderRadius: '8px', border: 'none', background: 'var(--accent-gold)', color: '#000', fontSize: '12px', fontWeight: 800, cursor: 'pointer' }}
                              >
                                {isEn ? 'Edit' : 'Editar'}
                              </button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  );
                })()}
              </div>
            </div>
          )}

          {/* SESSION PREVIEW MODAL */}
          {selectedSession && (
            <div className="modal-overlay-pdf" onClick={() => setSelectedSession(null)}>
              <div className="session-preview-modal" onClick={e => e.stopPropagation()}>
                <div className="preview-content">
                  <div className="preview-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <div>
                      <h2>{selectedSession.title || selectedSession.titulo || (isEn ? 'Untitled' : 'Sin título')}</h2>
                      <span className="date-full">
                        {selectedSession.date || selectedSession.fecha || ''} · {selectedSession.time || selectedSession.hora || ''}
                      </span>
                    </div>
                    <button className="btn-close-pdf" style={{ color: 'var(--text-primary)', marginTop: '-10px', marginRight: '-10px' }} onClick={() => setSelectedSession(null)}>✕</button>
                  </div>
                <div className="preview-stats">
                  <div className="p-stat"><strong>{selectedSession.duration || selectedSession.duracion || 0}</strong><span>{t('sesiones.preview.min')}</span></div>
                  <div className="p-stat"><strong>{(selectedSession.blocks || selectedSession.bloques || []).length}</strong><span>{t('sesiones.preview.blocks')}</span></div>
                  <div className="p-stat"><strong>{selectedSession.intensity || selectedSession.intensidad || (isEn ? 'Medium' : 'Media')}</strong><span>{t('sesiones.preview.load')}</span></div>
                </div>
                
                <div className="preview-files">
                  {(() => {
                    const linkedPiz = selectedSession.linkedPizarraId ? pizarras.find(p => p.id === selectedSession.linkedPizarraId) : null;
                    const fallbackImg = (selectedSession.blocks || selectedSession.bloques || []).find(b => b.imagenProtocolo)?.imagenProtocolo;
                    const diagramUrl = (linkedPiz && linkedPiz.thumbnail) || fallbackImg;
                    if (!diagramUrl) return null;
                    return (
                      <div className="protocolo-card" style={{marginTop: '0', marginBottom: '15px', padding: '8px', display: 'flex', justifyContent: 'center', background: '#f8fafc', border: '1px solid var(--border-light)', borderRadius: '12px', overflow: 'hidden'}}>
                        <img src={diagramUrl} alt="Diagrama Principal" style={{ maxWidth: '100%', maxHeight: '200px', objectFit: 'contain' }} />
                      </div>
                    );
                  })()}
                  {selectedSession.objectives && (
                    <div className="protocolo-card" style={{marginTop: '0', marginBottom: '15px'}}>
                      <h4>{isEn ? 'Objectives' : 'Objetivos'}</h4>
                      <p style={{fontSize: '0.9rem', color: 'inherit'}}>{selectedSession.objectives}</p>
                    </div>
                  )}
                  {selectedSession.linkedPizarraId && (() => {
                    const linkedPiz = pizarras.find(p => p.id === selectedSession.linkedPizarraId);
                    if (!linkedPiz) return null;
                    return (
                      <div className="protocolo-card" style={{marginTop: '15px', marginBottom: '15px', padding: '15px', border: '1.5px solid #2d4a2d', borderRadius: '12px', background: '#0f1a0f'}}>
                        <h4 style={{display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--accent-gold)', margin: '0 0 10px 0', fontSize: '12px', fontWeight: '800', textTransform: 'uppercase'}}>
                          🎬 {isEn ? 'Linked Animation' : 'Animación Vinculada'}
                        </h4>
                        <div style={{display: 'flex', gap: '12px', alignItems: 'center'}}>
                          {linkedPiz.thumbnail ? (
                            <img 
                              src={linkedPiz.thumbnail} 
                              alt="Miniatura Pizarra" 
                              style={{width: '90px', height: '60px', objectFit: 'cover', borderRadius: '8px', border: '1px solid rgba(255,255,255,0.1)'}} 
                            />
                          ) : (
                            <div style={{width: '90px', height: '60px', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#000', borderRadius: '8px', color: '#888', fontSize: '10px'}}>
                              {isEn ? 'Board' : 'Pizarra'}
                            </div>
                          )}
                          <div style={{flex: 1, minWidth: 0}}>
                            <div style={{fontWeight: '700', fontSize: '13px', color: 'white', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap'}}>{linkedPiz.title || (isEn ? 'Animation' : 'Animación')}</div>
                            <div style={{fontSize: '11px', color: '#888', marginTop: '4px'}}>
                              {linkedPiz.framesCount || 0} {isEn ? 'Frames · Tactical animation' : 'Frames · Animación táctica'}
                            </div>
                          </div>
                        </div>
                        <div style={{display: 'flex', gap: '10px', marginTop: '12px'}}>
                          <button 
                            className="btn-primary" 
                            style={{flex: 1, padding: '8px 12px', fontSize: '12px', minHeight: '36px'}}
                            onClick={() => {
                              window.location.href = `/pizarra?id=${linkedPiz.id}`;
                            }}
                          >
                            👁 {isEn ? 'VIEW ANIMATION' : 'VER ANIMACIÓN'}
                          </button>
                        </div>
                      </div>
                    );
                  })()}
                  {selectedSession.files?.length > 0 && (
                    <div className="files-indicator">
                      <span>📎 {isEn ? `${selectedSession.files.length} attached files` : `${selectedSession.files.length} archivos adjuntos`}</span>
                      {selectedSession.files.map(f => (
                        f.url ? <button key={f.id} className="btn-text-small" onClick={() => setPdfPreview(f.url)}>{t('sesiones.preview.viewPdf')}</button> : null
                      ))}
                    </div>
                  )}
                </div>

                <div className="preview-blocks">
                  <h4>{t('sesiones.preview.structure')}</h4>
                  {(() => {
                    const blocks = selectedSession.blocks || selectedSession.bloques || [];
                    if (blocks.length === 0) {
                      return <p className="empty-blocks-text">{t('sesiones.preview.emptyBlocks')}</p>;
                    }
                    return blocks.map((b, i) => {
                      const blockImg = b.imageUrl || b.imagenProtocolo || b.image || b.photo || b.previewUrl;
                      return (
                        <div key={b.id || i} className="block-item-mini" style={{ display: 'flex', flexDirection: 'column', gap: '8px', padding: '12px', borderRadius: '10px', background: 'var(--bg-card)', border: '1px solid var(--border-light)', marginBottom: '8px' }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                            <span className="b-num" style={{ minWidth: '24px', height: '24px', borderRadius: '50%', background: 'var(--accent-gold, #c9a84c)', color: '#000', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', fontSize: '12px' }}>{i + 1}</span>
                            <div className="b-info" style={{ flex: 1 }}>
                              <strong style={{ display: 'block', fontSize: '14px' }}>{b.name || b.nombre || (isEn ? 'Block' : 'Bloque')}</strong>
                              <span style={{ fontSize: '12px', opacity: 0.7 }}>{b.duration || b.duracion || 0} min · {b.type || b.tipo || ''}</span>
                            </div>
                          </div>
                          {(b.description || b.descripcion) && (
                            <p style={{ fontSize: '12px', opacity: 0.85, margin: '2px 0 0 0', whiteSpace: 'pre-wrap' }}>{b.description || b.descripcion}</p>
                          )}
                          {blockImg && (
                            <div style={{ marginTop: '6px', borderRadius: '8px', overflow: 'hidden', border: '1px solid var(--border-light)', backgroundColor: '#f8fafc', padding: '4px', textAlign: 'center' }}>
                              <img src={blockImg} alt={b.name || 'Diagrama'} style={{ width: '100%', maxHeight: '200px', objectFit: 'contain', borderRadius: '6px' }} />
                            </div>
                          )}
                        </div>
                      );
                    });
                  })()}
                </div>
                
                <div className="preview-actions">
                  <GatedFeature feature="sessions" teamContext={activeTeamId} silent={true}>
                    <button
                      type="button"
                      className="btn-primary full-width"
                      style={{ marginBottom: '10px', backgroundColor: '#1B3A2D', color: '#ffffff', fontWeight: '800', border: '1px solid var(--accent-gold)', minHeight: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}
                      onClick={() => setRatingModalSession(selectedSession)}
                    >
                      <Star size={16} color="#D4A843" fill="#D4A843" />
                      {t('sessionRating.rateButton')} ({t('sessionRating.title')})
                    </button>
                  </GatedFeature>
                  <button
                    className="btn-primary full-width"
                    style={{ marginBottom: '10px', backgroundColor: '#22c55e', color: '#000', fontWeight: '800', border: 'none', minHeight: '44px' }}
                    onClick={() => setShowLiveField(true)}
                  >
                    {t('sesiones.preview.startLiveField')}
                  </button>
                  <button 
                    className="btn-primary full-width" 
                    style={{marginBottom: '10px'}} 
                    disabled={isGeneratingPDF}
                    onClick={() => {
                      if (!isProActive) {
                        setUpgradeModal({ open: true, message: isEn ? 'Session PDF export is a PRO feature. Upgrade to use it.' : 'La exportación de sesiones a PDF es una función PRO. Sube de nivel para usarla.' });
                        return;
                      }
                      setIsGeneratingPDF(true);
                      setTimeout(async () => {
                        try {
                          await generateSessionPDF(selectedSession, activeTeam, pizarras, captures, players, exercises);
                        } catch(err) {
                          console.error(err);
                          await showAlert("Error", isEn ? "Error generating PDF" : "Error al generar el PDF");
                        } finally {
                          setIsGeneratingPDF(false);
                        }
                      }, 150);
                    }}
                  >
                    {isGeneratingPDF ? t('sesiones.preview.generating') : t('sesiones.preview.exportPdf')}
                  </button>
                  <button 
                    className="btn-outline-gold full-width" 
                    style={{ marginBottom: '10px', minHeight: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', fontWeight: 'bold' }} 
                    onClick={() => handleShareSession(selectedSession)}
                  >
                    <Share2 size={16} /> {t('sesiones.preview.shareSession')}
                  </button>
                  <div style={{ display: 'flex', gap: '10px', marginBottom: '10px' }}>
                    <button 
                      className="btn-outline" 
                      style={{ flex: 1, backgroundColor: '#1B3A2D', color: 'white', border: 'none', minHeight: '44px', fontWeight: 'bold' }} 
                      onClick={() => handleAddToGoogleCalendar(selectedSession)}
                    >
                      {t('sesiones.preview.googleCal')}
                    </button>
                    <button 
                      className="btn-outline" 
                      style={{ flex: 1, backgroundColor: '#4CAF7D', color: 'white', border: 'none', minHeight: '44px', fontWeight: 'bold' }} 
                      onClick={() => handleExportICS(selectedSession)}
                    >
                      {t('sesiones.preview.ics')}
                    </button>
                  </div>
                  <button 
                    type="button"
                    className="btn-outline-gold full-width" 
                    style={{ marginBottom: '10px', minHeight: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', fontWeight: 'bold' }} 
                    onClick={(e) => handleEditSession(selectedSession, e)}
                  >
                    {t('sesiones.preview.editSession')}
                  </button>
                  <button className="btn-text-error full-width" onClick={() => handleDeleteSession(selectedSession.id)}>{t('sesiones.preview.deleteSession')}</button>
                </div>
              </div>
            </div>
          </div>
          )}
        </div>
      ) : activeTab === 'captures' ? (
        <div className="captures-grid">
          {captures.length === 0 ? (
            <div className="empty-state-full">
              <div className="empty-icon">🎨</div>
              <h3>{isEn ? 'No tactical captures' : 'No hay capturas de pizarra'}</h3>
              <p>{isEn ? 'Captures saved in the Tactical Board will appear here automatically.' : 'Las capturas que guardes en la Pizarra Táctica aparecerán aquí automáticamente.'}</p>
            </div>
          ) : (
            captures.map(cap => (
              <div key={cap.id} className="capture-card" onClick={() => setSelectedCapture(cap)}>
                <div className="capture-image-wrapper">
                  <img src={cap.thumbnail || cap.url} alt="Pizarra" loading="lazy" />
                  <div className="capture-overlay">
                    <span>👁 {isEn ? 'View' : 'Ver'}</span>
                  </div>
                </div>
                <div className="capture-info">
                  <span className="capture-name">{cap.title || cap.name || (isEn ? 'Tactical Capture' : 'Captura Táctica')}</span>
                  <span className="capture-date">
                    {cap.timestamp?.toDate ? cap.timestamp.toDate().toLocaleDateString(locale) : (isEn ? 'Recent' : 'Reciente')}
                  </span>
                </div>
              </div>
            ))
          )}
        </div>
      ) : (
        <div className="captures-grid">
          {pizarras.length === 0 ? (
            <div className="empty-state-full">
              <div className="empty-icon">🎬</div>
              <h3>{isEn ? 'No board animations' : 'No hay animaciones de pizarra'}</h3>
              <p>{isEn ? 'Create multi-frame animations in the Tactical Board to export or link to your sessions.' : 'Crea animaciones multi-frame en la Pizarra Táctica para exportarlas o vincularlas a tus sesiones.'}</p>
            </div>
          ) : (
            pizarras.map(piz => (
              <div key={piz.id} className="capture-card" onClick={() => setSelectedAnimation(piz)}>
                <div className="capture-image-wrapper">
                  {piz.thumbnail ? (
                    <img src={piz.thumbnail} alt="Animación" loading="lazy" style={{objectFit: 'cover'}} />
                  ) : (
                    <div style={{width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#111', color: '#888', fontSize: '14px', fontWeight: 'bold'}}>🎬 {isEn ? 'Board' : 'Pizarra'}</div>
                  )}
                  <div className="capture-overlay">
                    <span>👁 {isEn ? 'View Details' : 'Ver Detalles'}</span>
                  </div>
                </div>
                <div className="capture-info">
                  <span className="capture-name">{piz.title || (isEn ? 'Tactical Animation' : 'Animación Táctica')}</span>
                  <span className="capture-date">
                    {piz.framesCount || 0} {isEn ? 'Frames' : 'Frames'} · {piz.timestamp?.toDate ? piz.timestamp.toDate().toLocaleDateString(locale) : (isEn ? 'Recent' : 'Reciente')}
                  </span>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {/* MODAL VISTA CAPTURA PROFESIONAL (PANTALLA COMPLETA + ANOTACIONES + ZOOM) */}
      {selectedCapture && (
        <ImageModal
          isOpen={!!selectedCapture}
          onClose={() => setSelectedCapture(null)}
          images={captures.map(c => c.url || c.thumbnail).filter(Boolean)}
          initialIndex={Math.max(0, captures.findIndex(c => c.id === selectedCapture.id))}
          exercisesData={captures.map(c => ({
            name: c.title || c.name || (isEn ? 'Tactical Board Capture' : 'Captura de Pizarra Táctica'),
            type: isEn ? 'Tactical Board' : 'Pizarra Táctica',
            description: c.description || (isEn ? 'Capture exported from Mister11 Tactical Board.' : 'Captura exportada desde la Pizarra Táctica de Míster11.')
          }))}
        />
      )}

      {/* MODAL DESCARGANDO MP4 */}
      {exportingId && (
        <div style={{
          position: 'fixed', inset: 0, zIndex: 99999, background: 'rgba(0,0,0,0.92)', 
          display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'
        }}>
          <div style={{zIndex: 2, textAlign: 'center', color: 'white', padding: '20px', borderRadius: '12px', background: '#1A2E1A', border: '1px solid #4CAF7D'}}>
            <h2 style={{margin: '0 0 10px 0', fontSize: '1.5rem'}}>🎬 {isEn ? 'Downloading MP4 Video...' : 'Descargando Video MP4...'}</h2>
            <p style={{margin: 0, color: '#ccc'}}>{isEn ? 'Please wait a moment.' : 'Por favor espera un momento.'}</p>
            <div style={{marginTop: '20px', width: '40px', height: '40px', border: '4px solid rgba(76,175,125,0.3)', borderTop: '4px solid #4CAF7D', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto'}}></div>
            <style>{`@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}</style>
          </div>
          {/* Iframe invisible para forzar la compilación del video en segundo plano usando la Pizarra Táctica */}
          <iframe 
            src={`/pizarra?id=${exportingId}&autoExport=true`} 
            style={{ width: '1px', height: '1px', visibility: 'hidden', position: 'absolute' }}
            title={isEn ? "Auto-Exporter Frame" : "Marco de auto-exportación"}
          />
        </div>
      )}

      {/* MODAL VISTA ANIMACIÓN */}
      {selectedAnimation && (
        <div className="modal-overlay-capture" onClick={() => setSelectedAnimation(null)}>
          <div className="modal-content-capture" onClick={e => e.stopPropagation()}>
            <div className="modal-header-capture">
              <h3>{selectedAnimation.title || (isEn ? 'Tactical Animation' : 'Animación Táctica')}</h3>
              <button className="btn-close-pdf" onClick={() => setSelectedAnimation(null)}>✕</button>
            </div>
            <div className="modal-body-capture" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
              {selectedAnimation.thumbnail ? (
                <img src={selectedAnimation.thumbnail} alt="Animación" style={{ maxHeight: '350px', objectFit: 'contain', borderRadius: '8px' }} />
              ) : (
                <div style={{ width: '100%', height: '240px', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#111', color: '#888', borderRadius: '8px', fontSize: '18px', fontWeight: 'bold' }}>{isEn ? '🎬 Animation without thumbnail' : '🎬 Animación sin miniatura'}</div>
              )}
              <div style={{ margin: '15px 0', textAlign: 'center', color: '#ccc', fontSize: '14px' }}>
                <p><strong>{isEn ? 'Total Frames:' : 'Total de Frames:'}</strong> {selectedAnimation.framesCount || 0}</p>
                <p>{isEn ? 'The animation will be exported directly in MP4 format (Video).' : 'La animación se exportará directamente en formato MP4 (Video).'}</p>
              </div>
              <div className="capture-actions-float" style={{ display: 'flex', gap: '10px', justifyContent: 'center', position: 'static', marginTop: '10px' }}>
                 <button className="btn-primary" onClick={() => handleExportMP4(selectedAnimation)}>{t('sesiones.preview.exportMp4')}</button>
                 <button className="btn-text-error" onClick={() => handleDeleteAnimation(selectedAnimation)}>{t('sesiones.preview.deleteAnimation')}</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <button className="fab-session" onClick={handleCreateNew}>+</button>

      {pdfPreview && (
        <div className="modal-overlay-pdf" onClick={() => setPdfPreview(null)}>
          <div className="modal-content-pdf" onClick={e => e.stopPropagation()}>
            <div className="modal-header-pdf">
              <h3>{isEn ? 'PDF Preview' : 'Vista Previa del PDF'}</h3>
              <button className="btn-close-pdf" onClick={() => setPdfPreview(null)}>✕</button>
            </div>
            <div className="modal-body-pdf">
              <iframe src={pdfPreview} title={isEn ? "PDF Preview" : "Vista Previa del PDF"} width="100%" height="100%" style={{border: 'none'}}></iframe>
            </div>
          </div>
        </div>
      )}

      <UpgradeModal 
        isOpen={upgradeModal.open} 
        onClose={() => setUpgradeModal({ ...upgradeModal, open: false })}
        message={upgradeModal.message}
      />

      {/* MODAL COMPARTIR SESIÓN */}
      {shareModal.open && (
        <div className="modal-overlay-pdf" onClick={() => setShareModal(prev => ({ ...prev, open: false }))}>
          <div className="modal-content-pdf" style={{ maxWidth: '540px', height: 'auto', padding: '24px' }} onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <h3 style={{ margin: 0, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '8px' }}>
                <Share2 size={20} color="var(--accent-gold)" /> {isEn ? 'Share Training Session' : 'Compartir Sesión de Entrenamiento'}
              </h3>
              <button className="btn-close-pdf" onClick={() => setShareModal(prev => ({ ...prev, open: false }))}>✕</button>
            </div>

            {shareModal.loading ? (
              <div style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-secondary)' }}>
                <div style={{ width: '36px', height: '36px', border: '3px solid var(--accent-gold-light)', borderTopColor: 'var(--accent-gold)', borderRadius: '50%', animation: 'spin 1s linear infinite', margin: '0 auto 12px auto' }} />
                <p>{isEn ? 'Generating public link and preparing data...' : 'Generando enlace público y preparando datos...'}</p>
              </div>
            ) : (
              <div>
                <p style={{ color: 'var(--text-secondary)', fontSize: '0.9rem', marginBottom: '16px' }}>
                  {isEn ? 'Any coach or user with this link will be able to view the exercises and clone the session directly to their team.' : 'Cualquier entrenador o usuario con este enlace podrá ver los ejercicios y clonar la sesión directamente a su equipo.'}
                </p>

                <div style={{ background: 'var(--bg-app)', border: '1px solid var(--border-light)', borderRadius: '10px', padding: '12px', display: 'flex', gap: '8px', alignItems: 'center', marginBottom: '20px' }}>
                  <input
                    type="text"
                    readOnly
                    value={shareModal.shareUrl}
                    style={{ flex: 1, background: 'transparent', border: 'none', color: 'var(--text-primary)', fontSize: '0.88rem', fontWeight: 'bold', outline: 'none' }}
                  />
                  <button
                    className="btn-primary-new"
                    style={{ minHeight: '38px', padding: '0 14px', fontSize: '0.85rem', display: 'inline-flex', alignItems: 'center', gap: '6px' }}
                    onClick={handleCopyShareUrl}
                  >
                    {shareModal.copied ? <Check size={16} /> : <Copy size={16} />}
                    {shareModal.copied ? (isEn ? 'Copied!' : '¡Copiado!') : (isEn ? 'Copy Link' : 'Copiar Link')}
                  </button>
                </div>

                <div style={{ borderTop: '1px solid var(--border-light)', paddingTop: '16px' }}>
                  <span style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: 'bold', textTransform: 'uppercase' }}>{isEn ? 'Other Export / Transfer Options:' : 'Otras Opciones de Exportación / Transferencia:'}</span>
                  <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                    <button
                      className="btn-outline-gold"
                      style={{ flex: 1, minHeight: '40px', fontSize: '0.85rem', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}
                      onClick={() => exportSessionToJSONFile(shareModal.session, activeTeam?.nombre)}
                    >
                      <Download size={15} /> Archivo (.m11session)
                    </button>
                    <button
                      className="btn-outline-gold"
                      style={{ flex: 1, minHeight: '40px', fontSize: '0.85rem', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: '6px' }}
                      onClick={() => exportSessionToICSFile(shareModal.session)}
                    >
                      <Calendar size={15} /> iCalendar (.ics)
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* MODAL IMPORTAR SESIÓN */}
      {importModal.open && (
        <div className="modal-overlay-pdf" onClick={() => setImportModal(prev => ({ ...prev, open: false }))}>
          <div className="modal-content-pdf" style={{ maxWidth: '600px', height: 'auto', padding: '24px', maxHeight: '90vh', overflowY: 'auto' }} onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <h3 style={{ margin: 0, color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '8px' }}>
                <Download size={20} color="var(--accent-gold)" /> {isEn ? 'Import / Transfer Session' : 'Importar / Transferir Sesión'}
              </h3>
              <button className="btn-close-pdf" onClick={() => setImportModal(prev => ({ ...prev, open: false }))}>✕</button>
            </div>

            {/* Pestañas de Importación */}
            <div style={{ display: 'flex', gap: '10px', marginBottom: '20px', borderBottom: '1px solid var(--border-light)', paddingBottom: '10px' }}>
              <button
                className={`tab-switcher ${importModal.activeTab === 'link' ? 'active' : ''}`}
                onClick={() => setImportModal(prev => ({ ...prev, activeTab: 'link', error: '' }))}
              >
                🔗 {isEn ? 'By Link / Code' : 'Por Enlace / Código'}
              </button>
              <button
                className={`tab-switcher ${importModal.activeTab === 'file' ? 'active' : ''}`}
                onClick={() => setImportModal(prev => ({ ...prev, activeTab: 'file', error: '' }))}
              >
                📁 {isEn ? 'By File (.m11session / .json)' : 'Por Archivo (.m11session / .json)'}
              </button>
            </div>

            {importModal.activeTab === 'link' ? (
              <div>
                <p style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', marginBottom: '12px' }}>
                  {isEn ? 'Paste the web link or share code sent by another coach:' : 'Pega el enlace web o código de compartir que te haya enviado otro entrenador:'}
                </p>
                <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
                  <input
                    type="text"
                    placeholder={isEn ? 'e.g. https://www.mister11.app/shared/session/m11_ses_...' : 'Ej: https://www.mister11.app/shared/session/m11_ses_...'}
                    value={importModal.inputVal}
                    onChange={e => setImportModal(prev => ({ ...prev, inputVal: e.target.value }))}
                    style={{ flex: 1, padding: '10px 14px', background: 'var(--bg-app)', border: '1px solid var(--border-light)', borderRadius: '8px', color: 'var(--text-primary)', outline: 'none' }}
                  />
                  <button
                    className="btn-primary-new"
                    disabled={importModal.loading}
                    onClick={handleFetchSharePreview}
                  >
                    {importModal.loading ? (isEn ? 'Searching...' : 'Buscando...') : (isEn ? 'Search Session' : 'Buscar Sesión')}
                  </button>
                </div>
              </div>
            ) : (
              <div style={{ marginBottom: '20px' }}>
                <p style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', marginBottom: '12px' }}>
                  {isEn ? <span>Select a <code>.m11session</code> or <code>.json</code> file exported from Míster11:</span> : <span>Selecciona un archivo <code>.m11session</code> o <code>.json</code> exportado de Míster11:</span>}
                </p>
                <input
                  type="file"
                  accept=".m11session,.json"
                  onChange={handleSessionFileUpload}
                  style={{ display: 'block', width: '100%', padding: '12px', background: 'var(--bg-app)', border: '1px dashed var(--accent-gold)', borderRadius: '8px', color: 'var(--text-primary)', cursor: 'pointer' }}
                />
              </div>
            )}

            {/* Alerta de Error */}
            {importModal.error && (
              <div style={{ background: 'rgba(220, 38, 38, 0.15)', border: '1px solid #dc2626', color: '#f87171', padding: '10px 14px', borderRadius: '8px', fontSize: '0.88rem', marginBottom: '16px' }}>
                ⚠️ {importModal.error}
              </div>
            )}

            {/* Vista Previa de la Sesión Encontrada */}
            {importModal.previewSession && (
              <div style={{ background: 'var(--bg-app)', border: '1px solid var(--border-light)', borderRadius: '12px', padding: '16px', marginBottom: '20px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '10px' }}>
                  <div>
                    <span style={{ fontSize: '0.75rem', background: 'rgba(212, 168, 67, 0.2)', color: 'var(--accent-gold)', padding: '2px 8px', borderRadius: '10px', fontWeight: 'bold' }}>
                      {isEn ? 'Session Found' : 'Sesión Encontrada'}
                    </span>
                    <h4 style={{ margin: '6px 0 0 0', fontSize: '1.1rem', color: 'var(--text-primary)' }}>
                      {importModal.previewSession.title}
                    </h4>
                  </div>
                  <span style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', fontWeight: 'bold' }}>
                    {importModal.previewSession.duration} min
                  </span>
                </div>

                <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', margin: '0 0 10px 0' }}>
                  {isEn ? 'Category:' : 'Categoría:'} <strong>{importModal.previewSession.category}</strong> • {isEn ? 'Load:' : 'Carga:'} <strong>{importModal.previewSession.intensity}</strong> • {isEn ? 'Blocks:' : 'Bloques:'} <strong>{(importModal.previewSession.blocks || []).length} {isEn ? 'exercises' : 'ejercicios'}</strong>
                </p>

                {importModal.previewSession.objectives && (
                  <p style={{ fontSize: '0.85rem', color: 'var(--text-primary)', background: 'var(--bg-card)', padding: '8px 12px', borderRadius: '6px', margin: 0 }}>
                    🎯 <em>{importModal.previewSession.objectives}</em>
                  </p>
                )}

                <button
                  className="btn-primary-new full-width"
                  style={{ marginTop: '16px', minHeight: '44px', fontWeight: 'bold', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}
                  disabled={importModal.loading}
                  onClick={handleConfirmImportSession}
                >
                  <Download size={18} /> {isEn ? `Import to my Team (${activeTeam?.nombre || 'Active Team'})` : `Importar a mi Equipo (${activeTeam?.nombre || 'Equipo Activo'})`}
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* MODAL MODO CAMPO DE ENTRENAMIENTO EN VIVO */}
      {showLiveField && (
        <LiveFieldSession
          session={selectedSession || (sessions.length > 0 ? sessions[0] : null)}
          onClose={() => setShowLiveField(false)}
        />
      )}

      {/* Modal de Calificación de Jugadores en la Sesión */}
      <SessionPlayerRating
        isOpen={Boolean(ratingModalSession)}
        onClose={() => setRatingModalSession(null)}
        session={ratingModalSession}
        players={players}
        teamPath={(getTeamPath && activeTeamId ? getTeamPath(activeTeamId) : '') || (activeTeam?.id ? `equipos/${activeTeam.id}` : (activeTeamId ? `equipos/${activeTeamId}` : ''))}
      />

      {/* Custom Dialog Modal (Glassmorphism Premium) */}
      {modalConfig.isOpen && (
        <div 
          className="custom-modal-backdrop" 
          onClick={() => modalConfig.isConfirm && modalConfig.onConfirm(false)}
        >
          <div 
            className="custom-modal-card" 
            onClick={(e) => e.stopPropagation()}
          >
            <div className="custom-modal-icon">⚠️</div>
            <h3 className="custom-modal-title">{modalConfig.title}</h3>
            <p className="custom-modal-message">{modalConfig.message}</p>
            <div className="custom-modal-actions">
              {modalConfig.isConfirm && (
                <button 
                  type="button"
                  className="btn-modal-cancel" 
                  onClick={() => modalConfig.onConfirm(false)}
                >
                  {isEn ? 'CANCEL' : 'CANCELAR'}
                </button>
              )}
              <button 
                type="button"
                className="btn-modal-confirm" 
                onClick={() => modalConfig.onConfirm(true)}
              >
                {modalConfig.isConfirm ? (isEn ? 'ACCEPT' : 'ACEPTAR') : (isEn ? 'UNDERSTOOD' : 'ENTENDIDO')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Sesiones;
